programs.sol:
"""A sparse approximation to an assessment/verification response.

Outcome words are usually negative; checking them, referring to someone's
answers, and mentioning test scores strengthen that response. Chinese exam and
lottery results and bid documents have parallel rules. Java layout names and tool-call
markers are separate lexical responses. Small grammatical/formatting baselines
capture a little background activity, not the component's full lexical variation.
"""
import re

READS = ()
# Ordinary mention, then the stronger response when explicitly checked.
OUTPUTS = {
    'score': (-0.13, -0.43),
    'scores': (-0.29, -0.76),
    'answer': (0.01, -0.60),
    'answers': (-0.09, -0.82),
    'result': (0.0, -0.27),
    'results': (-0.06, -0.46),
    'solution': (0.0, -0.44),
    'solutions': (0.0, -0.38),
    'work': (0.0, -0.49),
    'signature': (-0.22, -0.55),
    'signatures': (-0.20, -0.55),
}
POSSESSIVES = {'my', 'your', 'their', 'our', 'his', 'her'}
CHECK = re.compile(
    r'\b(check(?:ing)?|verif(?:y|ying))\s*'
    r'(?:(?:my|your|their|our|his|her|the|a)\s*)?$', re.I)
FRAMING = (
    ({'do', 'does', 'did', 'done', 'doing'}, 0.032),
    ({'must', 'should', 'shall', 'need', 'needs'}, 0.024),
    ({'one', 'only', 'single'}, 0.039),
    ({'also', 'moreover', 'furthermore'}, 0.043),
    ({'same', 'another', 'again'}, -0.040),
    ({'very', 'super', 'extremely', 'really', 'highly'}, -0.051),
)
JAVA_LAYOUT = {
    '.TRAILING': 0.47,
    '.LEADING': 0.18,
    '.GroupLayout': -0.22,
    '.Alignment': -0.07,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    for words, baseline in FRAMING:
        if word in words:
            value = baseline
            break

    if word in OUTPUTS:
        value, checked = OUTPUTS[word]
        if word in {'answer', 'answers'} and not token.startswith(' '):
            value = 0.065 if word == 'answer' else 0.01
        if previous in POSSESSIVES:
            value -= 0.23 if word in {'answer', 'answers'} else 0.12
        if previous in {'correct', 'incorrect', 'wrong', 'final'}:
            if word in {'answer', 'answers'}:
                value = -0.22 if word == 'answer' else -0.37
        if word in {'score', 'scores', 'result', 'results'}:
            if previous.endswith('test') or previous == 'exam':
                value = {'score': -0.30, 'scores': -0.72,
                         'result': -0.09, 'results': -0.31}[word]
            elif word in {'score', 'scores'}:
                if previous in {'high', 'higher', 'highest', 'lowest', 'credit'}:
                    value = -0.28 if word == 'score' else -0.48
        if CHECK.search(recent[-45:]):
            value = checked
    elif word in {'point', 'mark'} and previous in {'check', '.check'}:
        value = -0.31
    elif word == 'key' and previous == 'answer':
        value = -0.31
    elif word in {'成绩', '的成绩'}:
        value = -0.55 if '考' in recent[-20:] else -0.27
    elif word == '开奖结果':
        value = -0.55
    elif word in {'文件', '保证金'} and recent.endswith('投标'):
        value = -0.56
    elif word == '分' and previous == '查':
        value = -0.56
    elif token == '<tool_call>':
        value = -0.236
    elif token in JAVA_LAYOUT:
        value = JAVA_LAYOUT[token]
    elif token == '\r':
        value = 0.081
    elif token == '\\t':
        value = 0.048
    elif token.endswith('《'):
        value = 0.16

    return (doc, (recent + token)[-100:], word), float(value)

"""Detect an opening parenthesis fused to a word, e.g. '(x' or '(data'.

Longer identifiers get stronger predictions. Whitespace before the opening
parenthesis, and print/control-statement contexts, reduce the response.
Bare or symbolic openings are weaker. A secondary response marks chat user
headers and fades with document position. Other tokens are predicted zero.
"""
READS = ()
PRINT_OR_CONTROL_WORDS = {
    'print', 'printf', 'println', 'if', 'IF', 'while', 'switch',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    word = (token.startswith('(') and len(token) > 1
            and token[1].isascii() and token[1].isalpha())
    value = 0.0
    if word:
        letters = len(token) - 1
        value = 0.66 if letters == 1 else 0.78
        value += 0.02 * max(0, min(letters, 10) - 3)
        if previous.strip() in PRINT_OR_CONTROL_WORDS:
            value -= 0.18
    elif token == '(':
        value = 0.29
    elif token in {'(-', '($', '(*', '(&'}:
        value = 0.20
    elif token.startswith(('(\n', '(\r', '(\\')):
        value = 0.15
    elif token.startswith(('("', "('", '({')):
        value = -0.08
    if word or token == '(':
        if previous[-1:].isspace():
            value -= 0.31
        elif previous[-1:].isdigit():
            value += 0.15
    if token == 'user' and previous == '<|im_start|>':
        value = 0.86 / (1 + max(0, position - 1) / 3.8) ** 0.68
    return (doc, position, token), float(value)

programs.haiku:
"""Layer 0 MLP down-projection, component 3396.

This component is weak and mostly token-driven. Its activation is near zero for most
tokens (std about 0.035), and what it does carry depends on which word is being read,
not on the words before it. Four word classes shift it, and everything else sits near
zero:

  - the end-of-reasoning tag `</think>`: strongly negative (about -0.23);
  - size and degree adjectives (small, high, low, great, least, wide, thin, ...):
    negative (about -0.07);
  - reflexive pronouns (myself, yourself, himself, ...): positive (about +0.06);
  - patent and academic boilerplate (herein, referred, reference, also, especially,
    simply, likely): positive (about +0.04);
  - CJK characters: slightly negative (about -0.004).

Every other token predicts about -0.001, its average. The program keeps no state: each
position's prediction depends only on the newest token.

These four classes explain only about 1% of the variance. A table with one value per
token would explain about a third, but that table is not a concept and is not included.
"""

READS = ()

THINK_TAG = {"</think>"}

SIZE_WORDS = {
    "great", "least", "low", "small", "wide", "narrow", "thin", "high", "large",
    "shallow", "minimum", "lower", "peak", "radius", "diameter", "width",
}

REFLEXIVE = {
    "myself", "yourself", "yourselves", "himself", "herself", "itself",
    "ourselves", "themselves",
}

BOILERPLATE = {"herein", "referred", "reference", "also", "especially", "simply", "likely"}


def is_cjk(text):
    return any(
        "一" <= c <= "鿿" or "぀" <= c <= "ヿ" or "가" <= c <= "힯"
        for c in text
    )


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    if text == "</think>":
        value = -0.23
    elif word in SIZE_WORDS:
        value = -0.066
    elif word in REFLEXIVE:
        value = 0.06
    elif word in BOILERPLATE:
        value = 0.04
    elif is_cjk(text):
        value = -0.004
    else:
        value = -0.001
    return carry, float(value)

programs.sol:
"""Predict the main lexical peaks: Greek omega, O vowel signs, and URLs.

Omega is strongest inside Greek words; sigma, nu, tau, final sigma and mu
also respond when they immediately follow omega. Split UTF-8 characters
have different strengths from whole-character tokens. URL scheme separators
and the 'on' in 'based on' have negative responses. Ordinary text is near zero.
This captures the large peaks rather than every token's small fluctuations.
"""
import unicodedata as ud

READS = ()

# These tokenizer IDs denote exactly a space plus an incomplete Greek UTF-8
# lead byte (CE or CF). Decoding them alone loses that distinction.
GREEK_LEAD_CE = 7851
GREEK_LEAD_CF = 17383

# Weaker positive responses to vowel letters in other writing systems.
VOWEL_LETTERS = {
    'ō': 1.7,
    'ó': 0.25,
    'å': 0.45,
    'Å': 0.45,
    'ウ': 0.6,
    'オ': 0.45,
    '우': 0.8,
    ' 우': 0.7,
    '오': 0.42,
    'و': 0.57,
    'ون': 0.68,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_char = '', ''
    else:
        previous, previous_char = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    fragmented = '\ufffd' in token
    if fragmented:
        completed = prefix.text_prefixes[-1][-1:]
        if completed != '\ufffd':
            word = completed
    base = ud.normalize('NFD', word)
    letter = base[:1] if len(word) == 1 else ''
    prev_base = ud.normalize('NFD', previous_char[-1:])
    after_omega = prev_base.startswith('ω')
    name = ud.name(word, '') if len(word) == 1 else ''
    value = 0.0

    if token == '://':
        scheme = previous.strip(' \t\n(\"-').lower()
        value = -3.9 if scheme in {'http', 'https'} else -1.4
        if scheme in {'http', 'https'} and not previous.startswith(' '):
            value = -3.75
    elif token == '.com':
        value = -0.8 if previous.strip().lower() == 'github' else -0.25
    elif word.lower() == 'omega':
        value = 2.8 if word == 'omega' else 2.35
    elif word.lower() == 'sigma':
        value = 0.97
    elif word.lower() == 'psi':
        value = 0.6
    elif letter == 'ω':
        if fragmented:
            value = 4.8 if '\u0301' in base else 4.3
        elif '\u0345' in base:  # iota subscript, not an ordinary omega
            value = 0.65 if '\u0342' in base else 1.65
        elif '\u0342' in base:  # circumflex
            value = 6.8
        elif len(base) > 1:     # accented omega
            value = 8.4
        elif previous_char and 'GREEK' in ud.name(previous_char[-1], ''):
            value = 7.9
        else:                  # standalone mathematical omega
            value = 3.5
    elif word == 'Ω':
        value = 3.4
    elif word in {'σ', 'ν', 'τ', 'ς', 'μ'}:
        ordinary = {'σ': 1.05, 'ν': 0.5, 'τ': 0.1, 'ς': 0.08, 'μ': 0.0}
        following = {'σ': 3.6, 'ν': 2.1, 'τ': 2.0, 'ς': 1.2, 'μ': 1.1}
        value = following[word] if after_omega else ordinary[word]
        if after_omega and len(prev_base) > 1 and word in {'σ', 'τ'}:
            value -= 0.7 if word == 'σ' else 0.4
    elif word in {'ψ', 'Ψ'}:
        value = 0.75 if fragmented else 1.2
    elif word in {'ό', 'Ό'}:
        value = 2.54 if fragmented else 0.56
    elif word == 'υ':
        value = 1.14 if fragmented else 0.35
    elif word == 'χ':
        value = 0.64 if fragmented else 0.17
    elif word == 'φ':
        value = 0.3
    elif 'VOWEL SIGN' in name and name.endswith((' O', ' AU', ' CANDRA O')):
        value = 1.6 if name.startswith('TIBETAN') else 3.3
    elif word == 'ֹ':  # Hebrew holam: the O vowel point
        value = 3.1
    elif token in VOWEL_LETTERS:
        value = VOWEL_LETTERS[token]
    elif prefix.token_ids[-1] == GREEK_LEAD_CE:
        value = -0.2
    elif prefix.token_ids[-1] == GREEK_LEAD_CF:
        value = 0.86
    elif word == 'on' and previous.strip().lower() == 'based':
        value = -1.18 if previous.strip() == 'Based' else -1.05
    elif word in {'on', 'in'} and previous.strip().lower() == 'posted':
        value = -1.1 if word == 'on' else -1.4
    return (doc, token, word), value

programs.haiku:
"""Greek-letter detector for the output of MLP neuron 3398 of layer 0.

The component writes a large positive value when the token is the letter omega (ω, ώ, ῶ),
a smaller one for capital Ω, and small positive values for a handful of other Greek letters
(σ, ψ, ν, υ, φ, χ, τ). Omega is strongest inside Greek text (about 8) and weaker when it sits
in Latin text, e.g. the angular frequency in "d/dt" (about 3.5). The word "omega" gives 2.5.
Separately it goes negative (about -3.7) on the "://" of a URL, and on " on" after "based"
(about -1). Every other token gives 0. Letters are matched by their Unicode base letter, so
accents and breathing marks don't matter."""

import unicodedata

READS = ()

# Typical activation per Greek base letter (accents folded away), from training text.
GREEK_BASE = {
    "SIGMA": 1.2, "PSI": 0.9, "NU": 0.75, "UPSILON": 0.3, "PHI": 0.3,
    "CHI": 0.2, "TAU": 0.2,
}


ON_AFTER = {"based", "posted", "rely", "relies"}   # "based on": " on" is negative


def is_greek(ch):
    return "Ͱ" <= ch <= "Ͽ" or "ἀ" <= ch <= "῿"


def greek_context(prefix, n=30):
    """True when the last n characters of the text hold any Greek letter."""
    text = "".join(prefix.token_strings[-n:])[-n:]
    return any(is_greek(ch) for ch in text)


def base_letter(ch):
    """'ώ' -> 'OMEGA', 'ς' -> 'FINAL SIGMA', 'a' -> '' (not Greek)."""
    name = unicodedata.name(ch, "")
    if not name.startswith("GREEK") or " LETTER " not in name:
        return ""
    return name.split(" LETTER ")[1].split(" WITH ")[0]


def value(token, prev, greek):
    if token == "://":
        return -3.7
    if token == " on" and prev.strip().lower() in ON_AFTER:
        return -1.0
    if token.strip().lower() == "omega":
        return 2.5
    if len(token) != 1:
        return 0.0
    base = base_letter(token)
    if base == "OMEGA":
        if "CAPITAL" in unicodedata.name(token):
            return 3.8
        return 8.0 if greek else 3.5
    return GREEK_BASE.get(base, 0.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    return None, float(value(token, prev, greek_context(prefix)))

programs.sol:
"""Detect short 'ri' spellings rather than a topic or meaning.

The largest responses are unfinished pri / при syllables. Bare ri,
consonant+ri, and a few longer spelling families respond less strongly.
Several other scripts have analogous short syllables. Long words merely
containing ri are usually ignored. The reciprocal phrase 'each other'
is a separate, negative response. No earlier document is consulted.
"""
import unicodedata

READS = ()


def response(token):
    word = token.strip().strip('._@(-')
    s = word.lower()
    spaced = token.startswith(' ')
    if s == 'при':
        return 3.5
    if s == 'ри':
        return 2.0
    if s in ('три', 'рит'):
        return 1.4
    if s.startswith(('при', 'три')):
        return 1.3 * .78 ** max(0, len(s) - 4)
    if word == 'リ':
        return .9
    if len(word) == 2 and word.endswith('リ'):
        return 1.3
    if word.endswith('り'):
        return .3
    if word == '리':
        return .4
    if len(word) <= 3 and word.endswith('ري'):
        return 1.0
    if s in ('ř', 'př', 'przy'):
        return .75 if s == 'ř' else 1.0
    plain = ''.join(c for c in unicodedata.normalize('NFD', s)
                    if unicodedata.category(c) != 'Mn')
    if plain != s and plain.endswith('ri'):
        return 1.0
    s = plain
    if s == 'pri':
        return 5.0
    if s == 'ri':
        return 1.9 if spaced else (4.3 if word.isupper() else 3.5)
    if s.endswith('ri'):
        before = s[:-2]
        if before in ('b', 'f', 's'):
            return 3.0
        if before == 'c':
            return 2.6 if spaced else 1.7
        if before in ('t', 'g', 'st', 'at', 'et'):
            return 2.2
        if len(before) < 4:
            return 1.5 if word[:1].isupper() else 1.0
        return .4
    if s.startswith('prior'):
        base = 2.05 if spaced and word.islower() else 2.8
        return base * .85 ** (len(s) - 5)
    if s == 'priv' or s.startswith('private'):
        return .8 if token.startswith('\t') else 1.2
    if s == 'prim':
        return 1.6
    if s.startswith('primar'):
        return .9 * .85 ** max(0, len(s) - 7)
    if s.startswith('overrid'):
        return 1.2 if word[:1].isupper() else 2.2
    if s == 'crit':
        return 1.25
    if s.startswith('critical'):
        return .65
    if s.startswith('criteria'):
        return .6 if word[:1].isupper() else .3
    if s.startswith('trial'):
        return 1.0
    if s.startswith(('griev', 'grief')):
        return 2.3 if s == 'griev' else .8
    if s == 'orig':
        return 1.3
    if s.startswith('rior'):
        return 2.0 * .92 ** (len(s) - 4)
    if s.startswith('ri'):
        tail = s[2:]
        if tail.startswith(('ng', 'nt', 'sk', 'ght')):
            return .05
        scale = .8 if spaced else 1.0
        return scale * .65 ** (len(tail) - 1)
    if 'ri' in s:
        return .5 if len(s) == 4 else 0.0
    if s in ('tr', 'pr', 'ry', 'ru', 'apr'):
        if spaced and s == 'tr':
            return 0.0
        return .5 if word.isupper() or s in ('ru', 'apr') else .3
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = response(token)
    if (token.strip().lower() == 'other' and prefix.position > 0
            and prefix.document_ids[-1] == prefix.document_ids[-2]
            and prefix.token_strings[-2].strip().lower() == 'each'):
        value = -1.35
    return None, value

"""Approximate a data-handling lexical feature, especially tables and GUI forms.

'Data' is the strongest common cue. Spreadsheet words, content-access methods,
and form/data-field identifiers also give positive predictions. Fading topic
memories help distinguish cells/formulas/controls from other senses. Identifier
case and call/member syntax adjust the magnitude. Memories reset per document.
This is partial: numerous small unrelated lexical responses remain unmodeled.
"""
import re

READS = ()

SPREADSHEETS = set('''excel spreadsheet spreadsheets worksheet worksheets
                       workbook workbooks xlsx'''.split())
CODE = set('''function class public private return import def const var let
              array string int boolean null self this'''.split())
BIOLOGY = set('''protein proteins cancer tumor immune lymphocyte lymphocytes
                 stem blood receptor receptors apoptosis gene genes
                 tissue tissues'''.split())
WIDGETS = set('''textbox textboxes combobox listbox checkbox datagrid gridview
                 imageicon jlabel joptionpane jtextfield jpanel'''.split())
LAYOUTS = set('''borderlayout borderstyle flowlayout gridlayout
                 gridbagconstraints'''.split())
DOM_CONTENT = {'innerhtml', 'outerhtml', 'textcontent', 'nodetype'}
ACCESS_VERBS = {'get', 'set', 'read', 'write', 'find', 'show'}
CONTENT = {'value', 'text', 'attribute', 'parameter', 'string', 'element', 'dialog'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip()
    raw = re.findall(r'[A-Za-z]+', bare)
    split = re.sub(r'([a-z])([A-Z])', r'\1 \2', bare)
    words = re.findall(r'[a-z]+', split.lower())
    word = ''.join(words)
    terms = set(words)
    capital = bool(raw and raw[0][0].isupper())
    space = token.startswith(' ')
    dot = bare.startswith('.')
    paren = bare.startswith('(')
    camel = len(words) > len(raw)
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    sheet, code, bio, ui = (0.0,) * 4 if first else carry[1:]
    sheet = min(1.0, sheet * 0.99 + 0.5 * bool(terms & SPREADSHEETS))
    code = min(1.0, code * 0.99 + 0.2 * bool(terms & CODE))
    bio = min(1.0, bio * 0.99 + 0.25 * bool(terms & BIOLOGY))
    ui = min(1.0, ui * 0.99 + 0.5 * (word in WIDGETS | LAYOUTS))

    value = 0.002 + 0.015 * sheet - 0.008 * code + 0.017 * ui
    if word == 'data':
        value = (0.77 - 0.14 * space + 0.14 * capital + 0.06 * dot
                 - 0.07 * paren + 0.16 * sheet + 0.17 * code - 0.19 * bio)
    elif word in {'metadata', 'resultset', 'filereader'}:
        value = 0.26 + 0.05 * space + 0.09 * code
    elif word in {'dataframe', 'datasource', 'datatable'}:
        value = 0.40 + 0.15 * dot
    elif word in {'dataset', 'datasets'}:
        value = 0.05 + 0.2 * capital + 0.15 * dot
    elif 'databind' in word:
        value = 1.8
    elif 'data' in terms or word.endswith('data'):
        value = 0.7 + 0.2 * capital + 0.15 * dot
        if terms & {'adapter', 'reader', 'grid', 'view'}:
            value += 0.4
    elif '数据' in bare:
        value = 0.58
    elif 'データ' in bare or '데이터' in bare:
        value = 0.38
    elif word in {'excel', 'spreadsheet', 'spreadsheets', 'xlsx'}:
        value = 0.25 + 0.4 * sheet + 0.07 * code
    elif word in {'workbook', 'workbooks'}:
        value = 0.6 + 0.3 * sheet
    elif word in {'worksheet', 'worksheets'}:
        value = 0.2 + 0.2 * sheet + 0.1 * code
    elif word in {'cell', 'cells'}:
        value = (0.26 + 0.11 * capital + 0.17 * dot + 0.24 * paren
                 + 0.8 * sheet + 0.31 * code - 0.38 * bio)
    elif word in {'formula', 'formulas'} or bare == '公式':
        value = 0.12 + 0.55 * sheet + 0.24 * code
    elif word in {'sheet', 'sheets'}:
        value = 0.33 - 0.18 * space + 0.44 * sheet + 0.13 * code
    elif word in {'range', 'ranges'}:
        value = 0.14 + 0.17 * capital + 0.25 * sheet + 0.18 * code
    elif word in {'row', 'rows', 'column', 'columns'}:
        value = 0.06 + 0.1 * capital + 0.1 * dot + 0.15 * sheet + 0.1 * code
    elif word in WIDGETS:
        value = 0.4 + 0.2 * ui
    elif word in LAYOUTS or word in DOM_CONTENT:
        value = 0.75
    elif word in {'control', 'controls'}:
        value = 0.05 + 0.14 * code - 0.17 * bio + 0.05 * ui
    elif word in {'criteria', 'criterion'}:
        value = 0.2 - 0.06 * space + 0.18 * capital + 0.26 * code
    elif word in {'value', 'values', 'field', 'fields', 'record', 'records'}:
        value = (0.1 - 0.08 * space + 0.07 * capital + 0.07 * paren
                 + 0.13 * sheet + 0.12 * code - 0.08 * bio + 0.11 * ui)
    elif word in {'varchar', 'nvarchar'}:
        value = 0.17 + 0.12 * space + 0.11 * capital
    elif word in {'colspan', 'rowspan'}:
        value = 0.85
    elif word in {'storage', 'localstorage', 'sessionstorage'}:
        value = 0.16 + 0.08 * code
        if word != 'storage':
            value += 0.4
    elif word in {'csv', 'xml', 'json', 'pandas'}:
        value = 0.17 + 0.06 * dot + 0.15 * paren
    elif word in {'export', 'report', 'summary'}:
        value = 0.2 - 0.09 * space + 0.1 * code
    elif (camel and terms & {'row', 'column', 'cell', 'field'}
          and terms & {'index', 'count', 'name', 'value', 'style'}):
        value = 0.6 + 0.25 * capital + 0.3 * dot
    elif word.endswith('eventargs') or (camel and 'changed' in terms):
        value = 0.7
    elif dot and word in {'substring', 'charat', 'tofixed'}:
        value = 0.55
    elif camel and words[0] in ACCESS_VERBS:
        value = 0.13 + 0.12 * dot + 0.14 * paren
        if terms & CONTENT:
            value = 0.38 + 0.2 * dot
        if terms & {'cell', 'cells'}:
            value = 1.25 + 0.4 * sheet
        if terms & {'bounds', 'header'}:
            value = 1.0
    elif camel:
        value = (0.13 - 0.05 * space + 0.06 * dot + 0.33 * paren
                 + 0.1 * sheet + 0.12 * code - 0.08 * bio)
    elif paren and words:
        value = 0.09 + 0.04 * sheet + 0.07 * code - 0.04 * bio + 0.06 * ui
    return (doc, sheet, code, bio, ui), float(value)

