READS = ()

DATA_WORDS = {"data", "metadata", "数据", "資料", "データ"}
SHEET_WORDS = {
    "sheet", "sheets", "worksheet", "worksheets", "spreadsheet",
    "spreadsheets", "workbook", "workbooks", "excel", "formula",
    "formulas",
}
CELL_WORDS = {"cell", "cells"}
CELL_ACCESSORS = {"getcell", "setcell", "getvalue", "setvalue", "getsheet"}
EXPORT_WORDS = {"export", "exports", "csv"}
FIELD_WORDS = {
    "record", "records", "field", "fields", "column", "columns",
    "value", "values", "json", "result", "results", "string",
}


def step(carry, prefix, upstream):
    word = "".join(ch for ch in prefix.token_strings[-1].casefold()
                   if ch.isalnum())
    if word in DATA_WORDS:
        return None, 0.55
    if word in SHEET_WORDS:
        return None, 0.50
    if word in CELL_ACCESSORS:
        return None, 0.65
    if word in CELL_WORDS:
        return None, 0.30
    if word == "orderby":
        return None, 0.45
    if word in EXPORT_WORDS:
