# Words naming operations or organized activities, rather than their objects.
ACTIVITIES = set('''
study research review check search output display support contact service
production addition release report reports training exchange activation
transition repair conversion execution recognition reduction selection
operation installation install download edit interview opening processing
'''.split())
NOMINAL_ACTIONS = set('''
inclusion exclusion inhibition survival approval
'''.split())
CHINESE_ACTIVITIES = set('''
