'''.split())


def activation(token, previous, first):
    word = token.strip().lower()
    prev = previous.strip().lower()
    value = 0.0
    activity = word in ACTIVITIES or word in NOMINAL_ACTIONS
    if word == 'control':
        value = 0.51 if token.startswith(' ') else 0.42
    elif word == 'controls':
