        if prev == 'with':
            value = 0.50
        if prev == 'to':
            value = 0.13
    elif word in {'控制', '控'}:
        value = 0.46
    elif word in {'考试', '考核'}:
        value = 0.36
    elif word in CHINESE_ACTIVITIES:
        value = 0.26 if word == '学习' else 0.18
        if previous in CHINESE_ACTIVITIES:
            value += 0.20
        elif previous in CHINESE_QUALIFIERS:
            value -= 0.30
    elif activity:
        value = 0.23 if word in NOMINAL_ACTIONS else 0.12
    elif word in {'include', 'includes', 'included'}:
        value = 0.09
    elif word == 'working':
