    elif token == '#include':
        value = 0.59 if first else 0.24
    elif token == '#!/':
        value = 0.48 if first else 0.20
    elif token == '<tool_call>':
        value = 0.10
    elif token in {'</tool_call>', '</tool_response>', '</think>'}:
        value = -0.06
    elif token == '<|im_end|>' and previous == '</tool_response>':
