"""A punctuation pulse: strongest for space-prefixed # and // within a line.

Indentation and line breaks weaken these pulses. For inline, space-prefixed
hashes, longer preceding words and early document positions strengthen them.
Repeated heading marks, URL slashes, preprocessor directives, percent signs,
and block-comment openers have separate, smaller responses. This predicts
surface forms, not semantic comments; ordinary text gets zero. State resets at every document boundary.
"""

READS = ()
PREPROCESSOR = {
    '#include', '#define', '#undef', '#if', '#ifdef', '#ifndef',
    '#else', '#elif', '#endif', '#import', '#pragma',
}


def line_marker(mark, token, previous, start, position):
    hash_sign = mark == '#'
    spaced = token.startswith(' ')
    white = bool(previous) and not previous.strip(' \t\r\n')
    if spaced:
        if white:
            spaces = len(previous) - len(previous.rstrip(' '))
            # The marker's space completes a four-column indentation.
            value = -1.1 if spaces % 4 == 3 else (
                -1.7 if spaces < 3 else -1.35
            )
            if not hash_sign:
                value -= 0.1
            if start:
                value += 0.6
        elif start:
            value = -0.7
        else:
            word = previous.strip()
            if hash_sign:
                value = -2.5
                if word.isalpha():
                    value = -2.6 - 0.08 * min(len(word), 10)
                elif word.isdigit():
                    value = -2.3
                value -= 0.5 if position < 8 else (0.2 if position < 32 else 0.0)
            else:
                value = -2.35
                if word.isalpha():
                    value -= 0.04 * min(len(word), 10)
                if position < 32:
                    value -= 0.1
    else:
        value = (-0.52 if white else -1.13) if hash_sign else (
            -0.63 if white else -0.95
        )
        if start:
            value = (-0.15 if white else -0.3) if hash_sign else -0.38
            if not hash_sign and previous.endswith('\n'):
                value = -0.24
    if token.endswith('\n') and not hash_sign:
        value *= 0.5
    if position == 0:
        if hash_sign:
            value = -4.82 if spaced else 0.57
        else:
            value = 0.06 if token.endswith('\n') else (
                -3.84 if spaced else -1.7
            )
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous, position = '', '', 0
    else:
        _, line, previous, position = carry
    token = prefix.token_strings[-1]
    mark = token.strip()
    spaced = token.startswith(' ')
    white = bool(previous) and not previous.strip(' \t\r\n')
    start = not line.strip()
    value = 0.0

    if mark in {'#', '//'}:
        value = line_marker(mark, token, previous, start, position)
    elif mark and set(mark) == {'#'}:
        if spaced:
            value = (-0.42 if start else -0.83) if white else (
                -1.58 if len(mark) == 2 else -1.23
            )
        else:
            value = -0.05 if start else (-0.77 if len(mark) == 2 else -0.52)
            if position == 0:
                value = -0.2 if len(mark) == 2 else -0.66
    elif '://' in mark:
        value = -0.24
    elif '//' in mark:
        if mark.startswith('///'):
            value = (-0.02 if spaced else 0.2) if start else (
                -0.33 if spaced else (-0.14 if white else -0.72)
            )
        elif mark.startswith('//!'):
            value = 0.0 if start else -0.3
        else:
            value = -0.7 if any(c in mark for c in '\"\'') else -1.5
    elif '#' in mark:
        if '&#' in mark:
            value = -0.34
        elif mark in PREPROCESSOR:
            value = -0.22
        elif mark.startswith('#!/'):
            value = 0.0
        elif mark.startswith('$('):
            value = 0.1
        elif any(c in mark for c in '\"\''):
            value = -0.65
        elif mark.endswith('#') and mark[0] in ':./=()':
            value = -1.35
        else:
            value = -0.35 if start else -0.8
    elif '<!--' in mark:
        value = -0.17 if start else (-0.35 if white else -1.15)
    elif '/*' in mark:
        if not start:
            value = (-0.25 if white else -1.02) if spaced else -0.1
    elif '%' in mark:
        if mark == '%' and spaced:
            value = (-0.35 if start else -0.53) if white else -0.82
        else:
            value = -0.25 if spaced and not white else -0.06
    elif mark == '--' and spaced:
        value = 0.0 if start else (-0.1 if white else -0.28)
    elif mark == '@':
        value = (-0.02 if start else -0.2) if spaced else 0.17
    elif mark.upper() == 'TODO':
