"""Approximate the response to a short token continuation after an n-like letter.

Recognize Latin, Cyrillic, Greek and Arabic n, and Korean syllables with final
n; exclude written backslash-n escapes. Short vowel-led or nasal-led pieces
respond most. Letter family and fragment length set the gain; another n later
in a vowel-led or other-letter fragment reduces it. Uppercase predecessors
add a boost, and long predecessors attenuate the response. Whitespace and
punctuation receive small values; all other contexts receive zero.
Only the preceding token is remembered, resetting at document boundaries.
This captures the main spelling pattern, not individual word-specific effects.
"""
import math
import unicodedata
READS = ()

# Gains for fragments of length 1, 2, 3, and 4 or more.
GAINS = {
    'e_like_vowel': (1.20, 1.05, 0.51, 0.42),
    'i_like_vowel': (1.09, 0.69, 0.42, 0.29),
    'other_vowel': (0.90, 0.52, 0.14, 0.15),
    'nasal': (0.68, 0.57, 0.53, 0.21),
    'lip_consonant': (0.37, -0.11, -0.08, -0.06),
    'other_letter': (0.47, 0.28, 0.02, 0.03),
}


def n_like(c):
    return bool(c) and (
        c.lower() in 'nнνن' or
        0xAC00 <= ord(c) <= 0xD7A3 and (ord(c) - 0xAC00) % 28 == 4
    )


def letter_class(c):
    base = ''.join(x for x in unicodedata.normalize('NFD', c.lower())
                   if not unicodedata.combining(x))
    if base in 'eеєηε':
        return 'e_like_vowel'
    if base in 'iyиіιυ':
        return 'i_like_vowel'
    if base in 'aouаоуыэяюαοω':
        return 'other_vowel'
    if base in 'nнνن':
        return 'nasal'
    if base in 'bmpбмпβμπ':
        return 'lip_consonant'
    return 'other_letter'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if previous and n_like(previous[-1]) and not previous.endswith('\\n'):
        size = max(len(text.strip()), 1)
        if text[:1].isalpha():
            kind = letter_class(text[0])
            value = GAINS[kind][min(size, 4) - 1]
            if any(n_like(c) for c in text[1:]):
                value -= {'e_like_vowel': 0.32, 'i_like_vowel': 0.42,
                          'other_vowel': 0.36, 'other_letter': 0.13}.get(kind, 0.0)
            if previous[-1].isupper():
                value += 0.19
        elif text[:1].isspace():
            value = (0.071, 0.045, 0.018, 0.012)[min(size, 4) - 1]
        else:
            value = (0.033, 0.050, -0.023, -0.033)[min(size, 4) - 1]
        length = len(previous.strip())
        value *= math.exp(-max(length - 3, 0) / 4)
        if length == 1:
            value *= 0.8
    return (doc, text), float(value)

programs.luna:
"""A small lexical cue: mark a piece that continues a word already in progress."""
import unicodedata

READS = ()


def is_word_char(ch):
    return bool(ch) and (ch.isalnum() or unicodedata.category(ch).startswith("M"))


def step(carry, prefix, upstream):
    i = prefix.position
    doc = prefix.document_ids[i]
    previous_doc, previous_char = carry if carry is not None else (doc, "")
    if previous_doc != doc:
        previous_char = ""

    token = prefix.token_strings[i]
    continuation = (
        bool(token)
        and not token[0].isspace()
        and is_word_char(previous_char)
        and is_word_char(token[0])
    )
    last = token[-1] if token else previous_char
    return (doc, last), (0.006 if continuation else 0.0)

