"""Mostly a negative detector for the token 'so', not a general causal reasoner.

Case, a leading space, and whether 'so' continues an existing word change
its strength. Smaller negative echoes occur for contrast/conclusion words,
soil/social/soft vocabulary, and a few 'so/su' syllables in other scripts.
'Do so' and 'if/or so' are weaker than ordinary 'so'.
The program uses only current and previous token spellings.
"""
import re

READS = ()
SO_TOKEN = re.compile(r"[^\w]*(so|So|SO)$")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = token.strip()
    lower = word.lower()
    spaced = token[:1].isspace()
    continuing = bool(previous[-1:].isalpha()) and token[:1].isalpha()
    match = SO_TOKEN.fullmatch(token)
    value = 0.0
    if match:
        spelling = match[1]
        if spelling == 'so':
            value = -2.5 if continuing else -5.05
            preceding_word = previous.strip().lower()
            if spaced and preceding_word in {'do', 'doing', 'done', 'does', 'did'}:
                value = -3.5
            elif spaced and preceding_word in {'if', 'or'}:
                value = -4.0
        elif spelling == 'So':
            value = -4.07 if spaced else -4.37
        else:
            value = -2.5 if continuing else -3.3
    elif lower == 'but':
        value = (-0.73 if spaced else -0.56) if word == 'but' else (
            -0.46 if spaced else -0.30)
    elif lower in {'thus', 'therefore', 'hence'}:
        value = -0.51 if word[:1].isupper() else (-0.15 if spaced else -0.45)
    elif lower == 'too':
        value = -0.94 if spaced else -0.75
    elif lower in {'social', 'society', 'societies', '社会', '社會'}:
        value = -0.8
    elif lower in {'soil', 'soils'}:
        value = -2.65 if lower == 'soil' else -1.9
    elif word in {'土', '土壤', '泥土'}:  # soil
        value = -1.5
    elif word in {'软', '軟', '柔软'}:  # soft
        value = -2.0
    elif lower == 'soft':
        value = -1.0 if spaced else -0.74
    # Connectives in Chinese and Japanese: 'so', 'because', and 'but'.
    elif word == '所以':
        value = -1.65
    elif word in {'ので', 'なので', 'だったので'}:
        value = -2.3
    elif word in {'但', '但是'}:
        value = -0.15
    elif word == '那么':
        value = -0.55
    # Written syllables resembling so/su, rather than English connectives.
    elif word == 'ソ':
        value = -2.5
    elif word == '苏':
        value = -3.9
    elif word == '소':
        value = -1.1
    elif lower == 'со':
        value = -1.9 if spaced else -0.8
    elif lower in {'su', 'су'}:
        value = -0.6
    return (doc, token), value

