    token = prefix.token_strings[-1]
    raw = token.strip().strip('._-/\\:;()[]{}<>\"\'@#$')
    word = raw.lower()
    plain = word.translate(PLAIN_A)
    accented = plain != word
    word = plain
    space = token[:1].isspace()
    value = 0.0
    if re.fullmatch(r'[бвгджзклмнпрстфхцчшщ]{0,2}аг', word):
        value = -1.5 if space else -2.8
    else:
        match = re.fullmatch(r'([a-z]*?)ag([a-z]*)', word)
        if match:
            onset, tail = match.groups()
            if any(c not in CONSONANTS for c in onset):
                value = -1.8 if not tail and len(onset) <= 2 else 0.0
            elif tail in ('', 's'):
                value = -3.8 if space else -4.4
                if not onset:
                    value = -3.6 if space else -3.3 if raw == 'Ag' else -5.0
                elif onset in ('j', 'p', 'v', 'sn'):
                    value = -2.3
                elif onset in ('fl', 'tr', 'st', 'pr'):
                    value = -2.7
                elif onset == 'd':
                    value = -3.1
                elif not space and raw in ('tag', 'lag', 'zag'):
                    value = -4.9
                if tail == 's':
                    value += 0.6
            elif tail.startswith('ain'):
                value = 0.0
            elif tail in ('e', 'es'):
                value = -0.4 if not onset else -0.2
            elif not onset and tail in ('a', 'g', 'h', 'ger', 'ged'):
                value = -2.5
            elif not onset and len(tail) <= 2 and tail != 'o':
                value = -1.7
            elif tail.startswith(('azin', 'nitud')) or word in ('magic', 'magn'):
                value = -1.8
            else:
                value = -0.8
    if accented:
        value *= 0.5
    return None, float(value)

