"""Layer-0 MLP down_proj component 3410: a "mark" word detector.

The component's job is lexical. It is switched on by the word "mark" and by words built on
it, and by a few related words: annotation words such as note, tag, comment and label, and
the Chinese words for mark and sign. The response depends on the current token alone.

For each token the program predicts the component's activation:
  * the word "mark" in any case or inflection (mark, marks, marked, marking, Mark, MARK) -> 6
  * other words containing "mark" (remark, markdown, benchmark, trademark) -> 2
  * market, marketing, marker -> 1
  * the bare word "ark" -> 2.5; Park, park, bark -> 1.2
  * annotation words (note, tag, comment, symbol, label, ...) -> 0.8
  * Chinese 标记 (mark) 3, 标志 (sign) 2, 标 1.5, 記 / 记 / 標 about 1 -> as listed
  * everything else -> 0
"""

READS = ()

MARK_WORDS = {"mark", "marks", "marked", "marking", "markings"}
ARK_WORDS = {"ark", "arks", "arking"}
PARK_WORDS = {"park", "parks", "parked", "parking", "bark"}
ANNOTATION_WORDS = {
    "note", "notes", "noted", "tag", "tags", "tagged", "comment", "comments",
    "commented", "symbol", "symbols", "label", "labels", "labeled", "labelled",
}
CHINESE = {"标记": 3.0, "标志": 2.0, "标": 1.5, "標": 1.1, "記": 0.8, "记": 0.8}


def activation(token: str) -> float:
    word = token.strip().strip("._/-").lower()
    if word in MARK_WORDS:
        return 6.0
    if "mark" in word:
        return 1.0 if ("market" in word or "marker" in word) else 2.0
    if word in ARK_WORDS:
        return 2.5
    if word in PARK_WORDS:
        return 1.2
    if word in ANNOTATION_WORDS:
        return 0.8
    return CHINESE.get(token.strip(), 0.0)


def step(carry, prefix, upstream):
    return None, activation(prefix.token_strings[-1])

programs.sol:
"""Respond to local decimal-digit transitions, especially nine.

A nine usually has positive activation. After another nine it is strongly
negative; a small digit after a large digit gives a positive response that
falls as the current digit increases. Three short digit profiles calibrate
these patterns, rather than a table of all hundred digit pairs.
Decimal separators and a single space weaken the digit-pair response.
Fullwidth and Chinese digits share the numerical rule; words for nine and
September (the ninth month) have positive responses. Other text is zero.
"""
READS = ()

# Profiles are indexed by the ordinary numerical value of the digit.
NINE_AFTER = (1.09, 1.22, 1.68, 1.40, 0.75, 1.62, 1.35, 0.95, 0.16, -4.04)
AFTER_NINE = (3.26, 2.42, 1.62, 0.72, 0.06, -0.28, -1.14, -2.28, -3.54, -4.04)
LOW_DIGIT_HEIGHT = (0.0, 0.0, 0.0, 0.95, 1.47, 0.91, 1.35, 1.99, 2.01)


def digit_pair(previous, digit):
    if digit == 9:
        return NINE_AFTER[previous] if previous >= 0 else 0.71
    if previous == 9:
        return AFTER_NINE[digit]
    if previous >= 3:
        height = LOW_DIGIT_HEIGHT[previous]
        value = max(-0.04, height - (0.27 + 0.10 * height) * digit)
        if digit >= 7 and (previous == 4 or previous >= 7):
            scale = 1 if previous == 4 else previous - 6
            value = -scale * (0.20 + 0.12 * (digit - 7))
        return value
    if previous == 0 and digit in (1, 2):
        return 0.48 if digit == 1 else 0.11
    if previous == 2:
        if 2 <= digit <= 5:
            return -0.24 if digit == 4 else -0.14
        if digit == 1:
            return 0.16
        if digit >= 7:
            return 0.11 if digit == 7 else 0.26
    return -0.10 if previous < 0 and digit == 8 else 0.0


# The same digit concepts in two common non-ASCII notations.
DIGIT_SCRIPTS = ("0123456789", "０１２３４５６７８９", "零一二三四五六七八九")


def digit_value(token):
    if len(token) == 1:
        for script in DIGIT_SCRIPTS:
            if token in script:
                return script.index(token)
    return -1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, separator, position = -1, "", 0
    else:
        _, previous, separator, position = carry
    token = prefix.token_strings[-1]
    digit = digit_value(token)
    value = 0.0
    if digit >= 0:
        value = digit_pair(previous, digit)
        if previous >= 0 and separator in (".", ","):
            if digit == 9:
                offset = 0.11 if separator == "." else 0.29
            elif digit <= 2:
                offset = 0.10 if digit == 1 else 0.04
            elif digit <= 5:
                offset = -0.08
            else:
                offset = -0.11 * (digit - 5)
            scale = 0.30 if separator == "." else 0.21
            value = scale * value + offset
        elif previous >= 0 and separator == " ":
            offset = 0.41 if digit == 9 else (-0.10 if digit <= 2 else 0.0)
            value = 0.29 * value + offset
        if position == 0 or (position == 1 and previous == digit):
            # The first digit, or its immediate repetition, has no earlier context.
            value = -0.56 if digit == 9 else 0.10
        elif position == 1 and previous == 9 and digit in (7, 8):
            value += 0.80 * (digit - 6)
        if previous < 0 and token == "九":
            value = 1.10
    else:
        word = token.strip().lower()
        if word in ("nine", "ninth", "ninety"):
            value = {"nine": 1.0, "ninth": 0.87, "ninety": 0.50}[word]
        elif word == "september":
            value = 0.42  # the ninth month
        elif word in ("sept", "sep"):
            value = 0.22
    if token in (".", ",", " ") and previous >= 0 and not separator:
        next_carry = (doc, previous, token, position + 1)
    else:
        next_carry = (doc, digit, "", position + 1)
    return next_carry, float(value)

