"""Approximate a small number-reading signal: later digits in a digit run get
an output that depends on their decimal value. The first digit is left alone.
"""
import unicodedata

READS = ()

# A coarse response curve for successive decimal digits; nine is an exception
# when it follows another nine, as in many 199x-style strings.
DIGIT_RESPONSE = (1.2, 1.1, 0.9, 0.6, 0.1, -0.3, -1.0, -2.3, -3.7, 1.2)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous_document, previous_character = carry or (None, "")
    if document != previous_document:
        previous_character = ""

    value = 0.0
    if text and text[-1].isdecimal():
        digit = unicodedata.decimal(text[-1])
        if len(text) > 1:
            before = text[-2]
        else:
            before = previous_character
        if before and before.isdecimal():
            if digit == 9 and unicodedata.decimal(before) == 9:
                value = -4.2
            else:
                value = DIGIT_RESPONSE[digit]

    last_character = text[-1] if text else previous_character
    return (document, last_character), float(value)

