import re

READS = ()

# Japanese particles: subject, object, topic, also, at/to, and/with,
# at/by, of, towards, and-such. Scores: isolated, attached, kanji-stem
# bonus, and event/thing nominalizer bonus (koto/mono).
JAPANESE_PARTICLES = {
    'が': (0.97, 2.28, 2.57, 2.34), 'を': (0.86, 3.84, 1.71, 0.60),
    'は': (0.65, 1.65, 2.31, 2.62), 'も': (0.71, 1.56, 1.65, 2.19),
    'に': (-0.12, 2.25, 0.79, 1.24), 'と': (0.50, 1.43, 1.70, 0.00),
    'で': (0.10, 1.72, 1.40, 1.75), 'の': (-0.06, 0.93, 1.32, 1.43),
    'へ': (-0.02, 0.90, 0.00, 0.00), 'や': (0.48, 1.06, 0.00, 0.00),
