KOREAN_GROUPS = (
    ('을 를', 1.10, 2.80), ('이 가', 0.65, 1.60),
    ('은 는', 0.48, 1.30), ('와 과 도 고 며 면', 0.60, 0.60),
    ('지만 므로 하며 하는 적인 하게 하여', 0.90, 0.10),
    ('에게 까지 부터 처럼 에서', 0.70, 0.20),
    ('면서', 1.56, 0.22), ('으로', 0.25, 1.81),
)
KOREAN_ENDINGS = sorted(((e, a, b) for es, a, b in KOREAN_GROUPS
                         for e in es.split()), key=lambda x: -len(x[0]))
BOUNDARIES = {
    '<|endoftext|>': 1.26, '<tool_response>': 1.20,
    '</tool_response>': -0.24, '<think>': -0.43, '</think>': -0.54,
