    if not s:
        return 0.0
    han = any('\u4e00' <= c <= '\u9fff' for c in s)
    if any('\u3041' <= c <= '\u309f' for c in s):
        if s in {'です', 'でした', 'ます', 'ました'}:
            return -0.4
        if s in {'ですが', 'ますが'}:
            return 0.8
        if 'ことができ' in s:
