"""layers.0.mlp.down_proj:3413 -- a token-text detector for Japanese/Chinese/Korean word
pieces that end in a grammatical particle or function character.

What it does, in plain terms. The component's activation is almost a fixed value for each
token (it barely depends on the surrounding text), so this program reads the current token's
text, decoded alone, and returns a value by these rules, strongest first:

  1. Japanese word-piece that mixes kanji with a hiragana particle at its end
     (人が, 事を, 時は, 人は, お金を): 2.8-6, strongest for が and を (about 5), then
     は と で も (about 4), then に の て (about 2-3). The strongest class.
  2. Japanese piece that is hiragana only and ends in a particle (ことが, ものを): 1.5.
  3. Chinese piece with a kanji ending in a grammatical function character
     (的 是 了 为 和 在 有 上 ...): 1.2.
  4. Korean piece ending in a particle or case ending (을 를 이 가 는 에 ...): 1.0.
  5. Single-token particles は が を も と: 0.7; other kanji+kana or hiragana-only pieces:
     0.6-0.7; other Hangul: 0.3; kanji-only pieces that end in content characters: 0.1.
  6. Document and tool boundaries: <|endoftext|>, <tool_response>: 1.2. The English quantifiers
     each, every, entire, until: 0.9. " like", "://": 0.7. <|im_end|>: 0.35.
  7. Punctuation tokens containing "!" (for example "!(" or " (!("): 0.6.
  8. Everything else (English words, code, katakana loanwords, spaces): 0.

Why: this captures most of the token-determined variance in a short, readable rule. It does not
model the long tail of rare tokens (which is most of the remaining error) or the small
context effects.
"""

READS: tuple[str, ...] = ()

JA_PARTICLES = set("はがをもにとでのてやか")
# Mean activation of a kanji+kana piece ending in each particle (from training rows).
KANJI_KANA_PARTICLE = {"が": 5.0, "を": 5.0, "は": 4.0, "も": 4.0, "と": 4.0, "で": 3.5,
                       "に": 2.8, "の": 2.8, "て": 2.0}
ZH_FUNCTION = set("的是了为和在有上于中到会都也还就")
KO_PARTICLES = set("을를이가은는에의도로")
QUANTIFIERS = {"each", "every", "entire", "until"}
BOUNDARY = {"<|endoftext|>", "<tool_response>"}


def _has(text, lo, hi):
    return any(lo <= ord(c) <= hi for c in text)


def _kanji(text):
    return _has(text, 0x4E00, 0x9FFF)


def _hiragana(text):
    return _has(text, 0x3040, 0x309F)


def _hangul(text):
    return _has(text, 0xAC00, 0xD7AF)


def value(token):
    """Activation predicted for one token's text (decoded alone)."""
    if token in BOUNDARY:
        return 1.2
    if token.strip().lower() in QUANTIFIERS:
        return 0.9
    if token in (" like", "://"):
        return 0.7
    if token == "<|im_end|>":
        return 0.35
    if len(token) == 1 and token in "はがをもと":
        return 0.7
    if _hangul(token):
        if len(token) > 1 and token[-1] in KO_PARTICLES:
            return 1.0
        return 0.3
    if len(token) < 2:
        return 0.0
    if _kanji(token):
        if _hiragana(token):
            return KANJI_KANA_PARTICLE.get(token[-1], 3.0) if token[-1] in JA_PARTICLES else 0.7
        if token[-1] in ZH_FUNCTION:
            return 1.2
        return 0.1
    if _hiragana(token):
        return 1.5 if token[-1] in JA_PARTICLES else 0.6
    if not any(c.isalnum() for c in token) and "!" in token:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    """Stateless: each position's value depends only on the newest token's text."""
    return None, float(value(prefix.token_strings[-1]))

