"""A partial approximation of selected library/API and structural responses.

It approximates strong responses to Java framework namespaces and selected I/O,
serialization, and UI APIs. Smaller rules cover structural delimiters, short
parenthetical labels, and several grammatical word classes. Unknown text stays
near zero; most word-specific variation remains unexplained. Delimiter responses
are stronger near a document's beginning.
"""

READS = ()

JAVA_FRAMEWORKS = {
    'springframework', 'eclipse', 'jface', 'bukkit', 'gwt',
    'vaadin', 'junit', 'googlecode',
}
JAVA_LOGGING_AND_ANNOTATIONS = {'extern', 'slf', 'stereotype'}
SERIALIZATION = {'dumps', 'toJson'}
INPUT_APIS = {'InputStreamReader', 'OpenHelper', 'ioutil'}
POSSESSIVE_PRONOUNS = {'mine', 'yours', 'hers', 'ours', 'theirs'}
TEMPORAL_LIMITS = {'before', 'until', 'till', 'while', 'during'}
ACCESS_MODIFIERS = {'public', 'private', 'protected'}
PLURAL_DEMONSTRATIVES = {'these', 'those'}
FOCUS_ADVERBS = {'especially', 'particularly'}

# Long-document level, initial boost, decay scale, and standalone value.
DELIMITERS = {
    '<|im_start|>': (0.055, 0.12, 8.0, 0.145),
    '<|im_end|>': (0.020, 0.18, 6.0, 0.198),
    '<think>': (0.195, 0.105, 10.0, 0.210),
    '</think>': (0.062, 0.13, 14.0, 0.138),
    '<tool_call>': (0.064, 0.095, 6.0, 0.158),
    '</tool_call>': (-0.100, 0.16, 3.5, 0.027),
    '<tool_response>': (-0.050, 0.15, 5.0, 0.090),
    '</tool_response>': (-0.150, 0.20, 3.5, 0.050),
}


def punctuation(s, stack):
    value = 0.0
    if s == ')':
        if not stack:
            value = -0.04
        else:
            length, numeric, math = stack[-1]
            if math:
                value = -0.035
            elif numeric and length:
                value = 0.095
            else:
                value = max(-0.025, 0.070 - 0.003 * length)
    elif s.strip() in {'[', '|', '/'}:
        value = 0.020
    elif s.strip() in {']', '}'}:
        value = -0.012
    elif s.strip() in {':', ';'}:
        value = 0.010
    elif s.strip() in {'"', '“', '”'}:
        value = -0.030
    elif s.strip() == '->':
        value = -0.038

    # Keep only the shape and length of each open parenthesis, not its text.
    for ch in s:
        if ch == ')':
            if stack:
                stack.pop()
        for state in stack:
            state[0] += 1
            state[1] = state[1] and ch.isdigit()
            state[2] = state[2] or ch in '+*=^$\\'
        if ch == '(':
            stack.append([0, True, False])
    return value


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, stack = 0, []
    else:
        _, position, stack = carry
    previous = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    word = s.strip()
    value = punctuation(s, stack)
    lower = word.lower()
    if lower in POSSESSIVE_PRONOUNS:
        value = 0.060
    elif lower in PLURAL_DEMONSTRATIVES:
        value = 0.045
    elif lower in TEMPORAL_LIMITS:
        value = -0.037
    elif lower in ACCESS_MODIFIERS:
        value = -0.045
    elif lower in FOCUS_ADVERBS:
        value = -0.070
    elif lower in {'too', 'enough'}:
        value = 0.070
    elif lower in {'one', 'few'}:
        value = 0.040
    elif lower in {'null', 'undefined'}:
        value = -0.055

    # Package names occur as both dotted namespaces and URL path segments.
    if s.startswith(('.', '/')):
        name = s[1:]
        if name == 'apache':
            if previous.strip() == 'org':
                value = 0.70
            elif previous == 'www':
                value = 0.34
            else:
                value = 0.51 if s[0] == '.' else 0.40
        elif s[0] == '.' and name in JAVA_FRAMEWORKS:
            value = 0.43
        elif s[0] == '.' and name in JAVA_LOGGING_AND_ANNOTATIONS:
            value = 0.40
        elif s[0] == '.' and name in SERIALIZATION:
            value = 0.40
        elif s[0] == '.' and name in {'hasNext', 'findViewById'}:
            value = 0.48
        elif s[0] == '.' and name in {'existsSync', 'readFileSync'}:
            value = 0.50
        elif s in {'/raw', '/questions'}:
            value = 0.45
    elif word in INPUT_APIS:
        value = 0.52

    # Explicit structural tokens, not ordinary text inside angle brackets.
    if s in DELIMITERS:
        base, boost, scale, standalone = DELIMITERS[s]
        value = (standalone if position == 0 else
                 base + boost / (1.0 + position / scale))

    # A long run of colons is a decorative source-code banner.
    if len(word) >= 6 and set(word) == {':'}:
        value = -0.60
    return (document, position + 1, stack), value

