"""Predict a character/string lexical feature, mostly from the newest token.

The spelling `char` fires most strongly, followed by `character(s)`, with
weaker responses to string/byte terminology and other `char...` spellings.
A few preceding words modulate the response: e.g. unsigned versus const char,
or the versus main character. There is also a separate strong response to
Chinese 城 ('city'). Uncovered tokens are predicted as zero; this is not a
semantic parser and does not model the component's many small responses.
"""

READS = ()
DELIMITERS = '._(<[/\\-,:=|\"\''

TEXT_TERMS = {
    'str': 0.55, 'string': 0.95, 'strings': 0.65,
    'byte': 1.15, 'bytes': 0.8, 'substring': 1.6, 'substr': 0.85,
    'varchar': 1.9, 'wchar': 1.9, 'charat': 1.95,
    'strcpy': 1.0, 'strlen': 1.05, 'strcmp': 0.4,
    'stringbuilder': 1.2, 'getstring': 0.75,
    'tostring': 0.4, 'fromstring': 0.65,
    'ascii': 1.05, 'unicode': 0.6, 'utf': 0.45,
    'tolowercase': 0.75,
