            value -= 0.5
        elif token.startswith(('<', '[')):
            value -= 1.9
        if not token[:1].isspace() and word == 'char':
            if previous[-1:].isalpha():
                value -= 0.2
        if previous == 'unsigned':
            value = 2.3
        elif previous in ('const', 'static'):
            value = 6.0
        elif previous == 'var':
            value = 4.5
        elif previous in ('first', 'last', 'next'):
            value -= 0.45
    elif lower == 'chars':
        value = 3.9
