            value -= 0.55
        elif previous in ('fictional', 'special'):
            value -= 0.45
        elif previous == 'player':
            value += 1.2
    elif lower.startswith('character'):
        value = 0.85
    elif lower == 'charset':
        value = 1.8 if token.startswith(' ') and word == 'charset' else 0.9
    elif lower.startswith(('charg', 'chart')) and not lower.startswith('charter'):
        value = 0.0
    elif lower.startswith('charter'):
        value = 1.65
    elif lower.startswith('charit'):
        value = 1.15 if lower == 'charitable' else 0.5
    elif lower.startswith('char'):
        value = 0.95
    elif lower.startswith(('caract', 'caratt', 'caráct', 'cará')):
        value = 0.7 if 'istic' in lower or 'ístic' in lower else 1.6
    elif lower.startswith('характер'):
        value = 0.6 if lower != 'характер' else 1.3
    elif lower == 'acters':
