# or code punctuation around them: " char", "Char", "_char", "CHARACTER" ...
CHAR_WORDS = {"char", "chars", "character", "characters"}
# Strings and bytes, the programming-type words for text.
STRING_WORDS = {"str", "string", "strings", "bytes", "byte", "substring", "substr"}


def _word(token):
    """The token's letters and digits only, lower-cased: " String" -> "string"."""
    return re.sub(r"[\W_]+", "", token).lower()


def step(carry, prefix, upstream):
    w = _word(prefix.token_strings[-1])
    if w in CHAR_WORDS:
        value = 4.2
    elif w == "varchar":
        value = 1.9
    elif w.startswith(("characteri", "caract")):
        value = 0.9
    elif w in STRING_WORDS:
        value = 0.8
    else:
        value = 0.0
    return carry, float(value)

