values; escaped and same-line openings are weaker. Type declarations are
intermediate. Smaller offsets cover C/C++ types, allocation and stream
syntax, null values, header directives, EOF and two conversation markers.

Only the last 256 decoded characters are retained, reset at document changes.
These rules capture the dominant pattern, not all token-specific variation.
"""
import re

READS = ()
CONTROL = re.compile(r'\b(?:else|try|finally|do|static)\s*$')
DECLARATION = re.compile(r'\b(class|namespace|struct|enum|interface)\b[^{};\n]*$')
STATEMENT = re.compile(r'\b(?:if|for|while|switch|func|fn|throws)\b[^{};\n]*$')


# Other common syntax with a smaller response than block openings.
TYPES = {'void', 'bool', 'struct', 'uint', 'const'}
ALLOCATORS = {'malloc', 'calloc', 'realloc'}


def other_syntax(token, before):
    word = token.strip()
    if word in ('null', 'nil'):
        return 0.13 if word == 'null' else 0.08
    if word == 'EOF':
        return -0.37
    if word in ('<tool_call>', '</think>'):
        return 0.15
    if word == 'NULL':
        sql = re.search(r'\b(?:DEFAULT|VARCHAR|COMMENT|INSERT|VALUES)\b', before)
        return -0.28 if sql else -0.01
    if word in TYPES:
        if word == 'uint':
            return -0.29
        if word == 'struct':
            return -0.16
        return -0.06 if word == 'const' else -0.11
    if word in ALLOCATORS:
        return 0.32
    if word.lstrip('(*,') == 'sizeof':
        return 0.75 if word[0] in '*,' else 0.4
    if word == 'strcpy':
        return 0.35 if token.startswith(' ') else 0.65
    if word == 'cout':
        return 0.45 if token[0].isspace() else 0.2
    if word == 'endl':
        return 0.18
    if word == 'std':
        return -0.13
    if word == '<<':
        if re.search(r'\b(?:cat|python[0-9]*|bash)\b[^\n]*$', before):
            return -0.13
        return 0.8 if before.rstrip().endswith('cout') else 0.29
    if word == '->':
        return -0.08 if '$' in before else 0.26
    if word.startswith('#') and word[1:] in (
        'define', 'include', 'ifndef', 'endif'
    ):
        return -0.22 if word != '#include' else -0.08
    if word == '.h':
        return -0.19
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = other_syntax(token, before)
    if '{' in token and '}' not in token:
        left, right = token.split('{', 1)
        context = (before + left).rstrip()
        newline = '\n' in right
        escaped = right.startswith('\\')
        paren = context.endswith(')')
        keyword = context.endswith('=>') or bool(CONTROL.search(context))
        declaration = DECLARATION.search(context)
        literal = context.endswith(('=', ':', '(', '[', ',', 'return'))
        if paren:
            value = -1.15 if newline else -0.66 if escaped else -0.95
            if not newline and not escaped and left == ')':
                value = -0.41
            if '++' in left:
                value -= 0.35 if newline else 0.2
        elif keyword:
            value = -1.05 if newline else -0.52 if escaped else -0.8
        elif literal:
            value = 0.0
        elif declaration:
            record_type = declaration[1] in ('struct', 'interface')
            value = -0.35 if record_type else -0.8
            if not newline:
                value = -0.15
        elif newline:
            value = -0.65 if left.startswith(' ') else -0.23
            if STATEMENT.search(context):
                value = -0.84
        elif escaped:
            value = -0.3 if left.startswith(' ') else -0.05
        if newline and value < -0.5:
            if '\r' in right:
                value -= 0.08
            if right.count('\n') > 1:
                value += 0.15
    return (doc, (before + token)[-256:]), float(value)

"""Approximate the component as a c/C spelling detector.

Negative values are strongest for short fragments and acronyms ending in c.
Internal c is weaker, while initial c, ch, and familiar adjective/noun
suffixes usually get small values. A bare c/C attached to the preceding
alphabetic token is stronger; Latin-c responses shrink at document starts.
Smaller rules cover accented c, Cyrillic ч/ц, other-script k letters,
short Latin k fragments, and incomplete Unicode characters.
This uses spelling and immediate context, not a token-identity table.
"""
import unicodedata

READS = ()


def spelling_score(raw):
    word = raw.strip()
    low = word.lower()
    size = len(word)
    space = bool(raw[:1].isspace())
    first_c = low.find('c')
    last_c = low.rfind('c')

    if low.endswith('c'):
        if low.endswith('ic'):
            return -0.78 if size <= 3 else (
                -0.44 if size <= 5 else -0.18)
        if size == 1 or not low[-2].isalpha():
            return -1.28 if space else -1.53
        if word.isupper():
            return -2.29
        return -1.97 if size <= 3 else -1.38

    if first_c >= 0:
        # Familiar adjective and noun suffixes contain c without behaving
        # like an isolated letter fragment.
        if low.endswith(('ical', 'ically')):
            return 0.04
        if (size >= 7 and low.endswith('ance')) or (
                size >= 8 and low.endswith(('ence', 'ction'))):
            return -0.04
        if size <= 6 and low.endswith('ace'):
            return -0.91
        if first_c == 0:
            if 'ch' not in low and size <= 2:
                return -0.24 if space else -0.7
            if not space and size == 3:
                return -0.3
            return -0.02
        if 'ch' in low:
            return -0.09
        if first_c <= 3:
            return -0.58 if size - last_c <= 3 else -0.35
        return -0.35 if 'ck' in low else -0.15

    if any(ch in low for ch in 'чц'):
        return -0.82 if size <= 2 else -0.37
    if any(ch in low for ch in 'кκک'):
        return -0.43 if size <= 2 else -0.23
    if any(ch != 'c' and unicodedata.normalize('NFD', ch)[0] == 'c' for ch in low):
        return -0.5
    if 'k' in low and size <= 3:
        return -0.15
    if '\ufffd' in low:
        return -0.18
    return -0.01


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    value = spelling_score(raw)
    if raw in ('c', 'C') and not first:
        # A letter attached to the preceding word, rather than standing alone.
        previous = prefix.token_strings[-2]
        value = -2.30 if previous[-1:].isalpha() else -1.30
    if first and 'c' in raw.lower():
        value *= 0.73
    return None, float(value)

"""A document-initial opening-delimiter response.

An isolated left parenthesis has the strongest response. Joining it to
letters weakens it; short capital-letter forms respond more than longer
words. Tokens beginning with an empty pair, (), have no such response.
Parentheses attached to punctuation get a small positive response.
A fullwidth left parenthesis and a bare left angle bracket also respond.
All later positions, and other initial tokens, are approximated by zero.
This captures a rare structural motif, not the varied lexical background.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    value = 0.0
    if carry is None or carry != doc:
        token = prefix.token_strings[-1]
        if token in {'(', ' ('}:
            value = 0.554 if token == '(' else 0.561
        elif token == '（':
            value = 0.329
        elif token == '<':
            value = 0.430
        else:
            text = token.lstrip(' ')
            if text.startswith('(') and not text.startswith('()'):
                suffix = text[1:]
                if suffix and suffix[0].isalpha():
                    if suffix[0].isupper():
                        value = 0.32 if len(suffix) == 1 else 0.17
                    else:
                        value = 0.18 if len(suffix) == 1 else 0.10
                elif suffix:
                    value = 0.08
    return doc, value

"""Approximate the response to the token immediately after English 'to'.

'Be' is strongest; auxiliaries and several common verbs are positive.
Familiar introducing phrases such as 'need to', 'have to', and 'seem to'
reduce the response. Some adverbs and function words are negative.
Leading hyphens, dots, and underscores are stripped. All-caps, and
title-case 'Be', weaken the prediction.
This uses two preceding tokens, resets at documents, and otherwise gives zero.
"""
READS = ()

# Strength of 'to be' in familiar constructions, versus a free infinitive.
STRONG_REDUCTION = {
    'need', 'needs', 'have', 'going', 'able', 'seem', 'seems',
    'seemed', 'seeming', 'ought', 'unable',
}
MEDIUM_REDUCTION = {
    'has', 'had', 'supposed', 'used', 'tend', 'tends', 'tended',
    'needing', 'having', 'got',
}
MILD_REDUCTION = {
    'want', 'wants', 'wanted', 'appear', 'appears', 'likely',
    'trying', 'try', 'tried', 'how', 'needed', 'allowed', 'believed',
    'assumed', 'happen', 'happens', 'happened', 'continue',
    'wanting', 'wish', 'willing', 'sure',
}
SMALL_REDUCTION = {
    'considered', 'expected', 'thought', 'said', 'like',
    'continues', 'continued', 'out',
}
PRONOUNS = {'it', 'this', 'that', 'you', 'me', 'us', 'them', 'there'}


def strength(before):
    if before in STRONG_REDUCTION:
        return 2.0
    if before in MEDIUM_REDUCTION:
        return 2.6
    if before in MILD_REDUCTION:
        return 3.3
    if before in SMALL_REDUCTION:
        return 4.0
    if before in PRONOUNS:
        return 4.6
    if before == 'not':
        return 5.0
    if before is None:
        return 7.6
    if not before:
        return 5.6
    if before in {'.', '!', '?'}:
        return 6.9
    return 5.45


def response(word, s):
    if word == 'be':
        return s
    if word == 'have':
        return 0.58 * s - 0.1
    if word == 'see':
        return 0.46 * s - 0.4
    if word == 'do':
        return 0.30 * s - 0.35
    if word == 'go':
        return 0.20 * s + 0.05
    if word in {'become', 'appear'}:
        return 0.24 * s + 0.25
    if word in {'come', 'receive', 'hear', 'watch', 'remain'}:
        return 0.20 * s + 0.1
    if word in {'work', 'say', 'know', 'think', 'learn', 'believe'}:
        return 0.24 * s - 0.3
    if word in {'make', 'use', 'get', 'find', 'show', 'look', 'read',
                'run', 'solve', 'check', 'write', 'take', 'meet'}:
        return 0.14 * s - 0.28
    if word in {'provide', 'play', 'follow', 'reach', 'achieve', 'serve',
                'live', 'stay', 'win', 'include', 'represent', 'begin'}:
        return 0.12 * s + 0.1
    if word in {'further', 'better', 'about'}:
        return -1.8
    if word in {'more', 'both', 'not', 'either', 'just', 'only', 'first'}:
        return -1.0
    if word.endswith('ly') and word.isalpha() and word not in {
            'apply', 'comply', 'rely', 'supply', 'multiply',
            'fly', 'imply', 'reply', 'family'}:
        return -0.8
    if word in {'this', 'that', 'your', 'our', 'you', 'which', 'what'}:
        return -0.35
    if word == 'the':
        return -0.08
    if word == 'a':
        return 0.22
    if word == 'help':
        return -0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, None, None)
    _, previous, before = carry
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('-._').lower()
    value = response(word, strength(before)) if previous == 'to' else 0.0
    if token.strip().isupper():
        value *= 0.45
    elif word == 'be' and token.strip().istitle():
        value *= 0.75
    return (doc, word, previous), float(value)

"""A short continuation after an f-ending fragment gets a positive signal.

Spaces largely break the pattern. Short letter fragments and capital F
strengthen it; inflections, double f and unlikely f-letter clusters weaken
it. Numbers and punctuation can also count. A fragment containing f
inhibits the signal; f-ending fragments at document starts are negative.
Cyrillic ф and Arabic ف behave similarly; ph and Japanese フ/ふ are weaker.
Only the previous token is remembered, with resets at document boundaries.
These spelling rules approximate, rather than memorize, fragment strengths.
"""
import unicodedata

READS = ()
F_LETTERS = 'fFфФف'
INFLECTIONS = {'s', 'es', 'ed', 'ing', 'ly'}


def script(c):
    name = unicodedata.name(c, '')
    for family in ('LATIN', 'CYRILLIC', 'ARABIC'):
        if family in name:
            return family
    return 'OTHER'


def letters(previous, s, family):
    if script(s[0]) != family:
        return 0.0
    if any(c in s for c in F_LETTERS):
        return -1.0 if len(s) == 2 else -0.35
    value = 1.25 - 0.18 * max(len(s) - 2, 0)
    value -= 0.45 * (s.isupper() or s.istitle())
    value += 0.18 * previous.endswith(('F', 'Ф'))
    value -= 0.3 * previous.lower().endswith('ff')
    value -= 0.2 * (s.lower() in INFLECTIONS)
    value -= 0.45 * (family == 'ARABIC')
    if family == 'LATIN':
        onset = unicodedata.normalize('NFD', s[0])[0].lower()
        if onset in 'aeou':
            value += 0.1
        elif onset.isalpha() and onset not in 'aeioulr':
            # F usually combines with a vowel, or the liquids L/R.
            value -= 0.45
    return max(0.0, value)


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    s = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, s)
    if not previous:
        value = 0.0
        if s.endswith(tuple(F_LETTERS)):
            value = -0.65 if len(s.strip()) < 4 else -0.2
        return carry, value

    last_f = max(previous.rfind(c) for c in F_LETTERS)
    if last_f >= 0:
        distance = len(previous) - 1 - last_f
        strength = 1.0 if distance == 0 else 0.15 / distance
        family = script(previous[last_f])
    elif previous.lower().endswith('ph'):
        strength, family = 0.3, 'LATIN'
    elif previous.endswith(('フ', 'ふ')):
        strength, family = 0.3, 'OTHER'
    else:
        return carry, 0.0

    contains_f = any(c in s for c in F_LETTERS)
    if not s or s[0].isspace():
        value = -0.08 if contains_f else 0.01
    elif s[0].isdigit():
        value = 0.58
    elif s[0].isalpha():
        value = letters(previous, s, family)
    elif contains_f:
        value = -0.27
    elif s in ("'", '-', '\\"'):
        value = 0.45
    elif s.startswith('\\'):
        value = 0.35
    else:
        value = 0.08 if len(s) <= 2 else 0.0
    return carry, float(strength * value)

"""Predict a mostly spelling-based response to p/P-initial token pieces.

Short pieces and capitals fire more strongly; pr/pl/ph onsets and pieces
inside an existing word fire less. Cyrillic pe, Greek pi, and other
p-syllable scripts also respond.
A single p can leave a response on its next word-fragment. Tool-call
markers, wide indentation, and long divider lines are secondary responses.
These rules approximate the common pattern, not individual token embeddings.
"""

READS = ()

# Pronunciation-equivalent onsets in Latin and Cyrillic spelling.
ONSET_ADJUSTMENT = {
    'pe': -0.21, 'po': -0.21, 'pu': -0.11, 'py': 0.13,
    'ph': -0.35, 'pl': -0.31, 'pr': -0.53,
}
CYRILLIC_ONSETS = str.maketrans('пПеоуылрх', 'pPeouylrh')
SHORT_PIECE_BONUS = (0.0, 0.17, 0.51, 0.51, 0.21, 0.07, 0.12, 0.04)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.lstrip()
    while word and not word[0].isalnum():
        word = word[1:]
    initial = word[:1]
    is_p = initial in ('p', 'P', 'п', 'П')
    value = 0.0
    if is_p:
        letters = ''.join(c for c in word if c.isalpha())
        n = len(letters)
        spelling = word.lower().translate(CYRILLIC_ONSETS)
        value = 1.09 if initial in ('p', 'P') else 1.47
        if n < len(SHORT_PIECE_BONUS):
            value += SHORT_PIECE_BONUS[n]
        if initial.isupper():
            value += 0.33
        if n > 1 and letters.isupper():
            value += 0.15
        value += ONSET_ADJUSTMENT.get(spelling[:2], 0.0)
        if spelling.startswith('pre'):
            value += 0.17
        if n > 4:
            if spelling.endswith('s'):
                value -= 0.14
            if spelling.endswith('ed'):
                value -= 0.07
            if spelling.endswith('ly'):
                value -= 0.22
        if token[:1].isspace():
            value += 0.03
        elif word != token:
            value += 0.06
        elif token[:1].isalpha() and previous:
            value -= 0.43
            if n <= 3:
                value -= 0.31
            if previous[-1].lower() == initial.lower():
                value -= 0.8
        if first:
            value -= 0.55
    elif initial in ('π', 'Π', 'پ'):
        value = 0.6
    elif initial and initial in 'ぱぴぷぺぽパピプペポ':
        value = 1.3
    elif initial and 0xAC00 <= ord(initial) <= 0xD7A3:
        # Hangul syllables beginning with the consonant pieup (aspirated p).
        value = 0.7 if (ord(initial) - 0xAC00) // 588 == 17 else 0.0
    elif previous in ('p', 'P', 'п', 'П') and token[:1].isalpha():
        value = 0.69
    elif token in ('<tool_call>', '</tool_call>'):
        value = 1.89
    elif token.isspace() and len(token) >= 16:
        value = 0.25
    else:
        stripped = token.strip()
        if (len(stripped) >= 12 and len(set(stripped)) == 1
                and stripped[0] in '-=_#'):
            value = 0.29

    # Keep only the trailing alphabetic word-fragment, resetting at delimiters.
    tail = ''
    for char in reversed(token):
        if not char.isalpha():
            break
        tail = char + tail
    if token and token.isalpha():
        tail = previous + tail
    return (doc, tail[-2:]), float(value)

