        value = GROUP_WORDS.get(character, value)
    # A group expression continues on an inflection or on the following 'of'.
    if value == 0.0 and previous_value < -1.0:
        if token.lower() == ' of':
            value = 0.41 * previous_value
        elif not token.startswith(' ') and word in {'s', 'es', 'ing', 'ings'}:
            value = 0.43 * previous_value
        elif not token.startswith(' ') and word in {'ed', 'а', 'у', 'ы', 'е'}:
            value = 0.35 * previous_value
    return (doc, word, value), float(value)

programs.luna:
"""Recognize group and collective-entity words, which are the component's
strongest lexical cues; also respond to the phrase 'group of'."""

READS = ()

GROUP_STEMS = (
    "group", "grupo", "gruppe", "grupp", "组", "群", "مجموعة",
)

OTHER_COLLECTIVES = (
    "team", "pair", "cluster", "choir", "club", "bunch", "bundle",
    "block", "pool", "population", "battalion", "troop", "gang",
    "guild", "collective", "族群", "團隊", "队伍",
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold().strip()

    if any(stem in word for stem in GROUP_STEMS):
        return None, -5.0

    if word == "of" and len(prefix) > 1:
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = prefix.token_strings[-2].casefold().strip()
        if same_document and any(stem in previous for stem in GROUP_STEMS[:5]):
            return None, -2.0

    if any(stem in word for stem in OTHER_COLLECTIVES):
