    if word in {'责任编辑', '責任編輯', '副主席', '研究员', '研究員', '院士'}:
        return -1.4
    if word in {'主席', '教授', '首席', '总理', '總理', '委员', '委員'}:
        return -0.95
    if word in {'新华社', '新華社', '中新网', '中新網',
                '日电', '日電', '日讯', '日訊'}:
