    if word in {'工作人员', '负责人', '市民', '网友',
                '法定代表', '首相', '總統', '总统'}:
        return -0.65
    if lower == 'reuters':
        return -0.9
    if lower in {'journalists', 'reporters'}:
        return -0.78
    if lower in {'journalist', 'reporter', 'journalism'} or lower in PUBLIC_ROLES:
        return -0.44
    if lower == 'minister' and before.rstrip().lower().endswith(('prime', 'chief')):
        return -0.45
    if lower in OCCUPATIONS:
