         "president", "President", "minister", "Minister", "senator", "Senator",
         "congressman", "Congressman", "ceo", "CEO", "chairman", "officials", "official",
         "professor", "人大", "市人大", "常委会", "法定代表", "副", "律师", "lawyer"}
NEWS = {"新华社", "日电", "Reuters", "晚报", "电视台", "新聞", "新闻", "消息", "热线",
        "报道", "宣传片", "消费者", "市民", "ニュース"}


def _word(token):
