programs.haiku:
"""Component layers.0.mlp.down_proj:3430 — a "be-verb after a subject" detector.

What it does: it goes strongly negative on the present-tense forms of the verb "to be"
(is, are, be, am, being, 's, 're, 'm, and the curly-apostrophe versions) when they follow
their subject, and is about zero everywhere else.

How strongly depends on what comes before the verb:
  - "it" / "It" as subject ("it is", "It's"):           strongest, about -3.2
  - "I" + "am" / "'m":                                    about -1.8
  - "they" / "we" / "you" + "are" / "'re":                about -1.7
  - a modal or "to" / "not" before "be" ("will be", "to be"): about -1.4
  - any other noun or pronoun subject:                    about -1.1
  - "was"/"were" is only negative after "it" (about -1.4).
  - "there is", "here is" (existential/locative) give ~0.
  - a possessive "'s" (after a noun) gives ~0.

Why: this component is a small piece of the residual-stream update for the copula, so
its job is to mark "a predicate follows" right after a copula, with the sign and size
set by the subject. The value is a rough lookup, not the model's own computation.
"""

READS = ()

# Forms of "to be" that act as copulas or auxiliaries.
BE_FORMS = {"is", "are", "be", "am", "being", "was", "were", "'s", "’s", "'m", "’m", "'re", "’re"}
CONTRACTION_S = {"'s", "’s"}
# Words that can come right before a bare "be" (modal, negation, infinitive "to").
MODALS = {"will", "would", "should", "may", "might", "must", "shall", "could", "can",
          "cannot", "to", "not", "also", "'ll", "’ll", "n't", "'t", "’t"}
# Subjects after which "'s" is a copula or auxiliary, not a possessive.
PRONOUN_S_SUBJECTS = {"that", "what", "he", "she", "this", "which", "who", "there", "it"}
EXISTENTIAL = {"there", "here"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()

    if tok not in BE_FORMS:
        return carry, 0.0
    if tok in ("was", "were"):
        return carry, -1.4 if prev == "it" else 0.0
    if prev in EXISTENTIAL:
        return carry, 0.0
    if tok == "am":
        return carry, -1.7 if prev == "i" else 0.0
    if prev == "it":
        return carry, -3.2
    if tok in CONTRACTION_S and prev not in PRONOUN_S_SUBJECTS:
        return carry, 0.0  # possessive, e.g. "John's"
    if prev == "i":
        return carry, -1.9
    if prev in ("they", "we", "you"):
        return carry, -1.7
    if prev in MODALS:
        return carry, -1.4
    return carry, -1.1

programs.luna:
"""Approximate the component's sparse negative response to forms of 'be'.

High-impact examples cluster on English be/is/are/was and on contractions
such as it's and you're; a few Spanish forms occur as well.  This rule gives
those lexical cues typical values and otherwise predicts zero.  It cannot
capture the strong contextual variation, or distinguish every use of 's.
"""
READS = ()

BE_VERBS = {"be", "is", "are", "am", "was", "being"}
CONTRACTIONS = {"'s", "’s", "'re", "’re", "'m", "’m"}
SPANISH_BE = {"es", "siendo"}
SUBJECTS = {
    "i", "it", "he", "she", "that", "there", "this", "what", "who",
    "we", "you", "they", "these", "those", "one",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    new_document = (
        prefix.position == 0
        or prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    at_word_start = raw[:1].isspace() or new_document
    if prefix.position and not new_document:
        if prefix.token_strings[-2][-1:].isalnum():
            at_word_start = raw[:1].isspace()
        else:
            at_word_start = True

    if word in CONTRACTIONS:
        same_document = prefix.position and not new_document
        previous = (
            prefix.token_strings[-2].strip().lower() if same_document else ""
        )
        return None, -1.8 if previous in SUBJECTS else 0.0
    if word in BE_VERBS and at_word_start:
        return None, -0.9 if word == "being" else -1.2
    if word in SPANISH_BE and at_word_start:
        return None, -0.5 if word == "es" else -0.4
    return None, 0.0

programs.sol:
"""Recognize production, goods, brands, and their commercial supply.

Industry, trade, manufacturers, and brands are strong negative cues; business,
products, food, farming, and product standards are weaker cues. Chinese and
Russian production terms express the same concepts. Familiar collocations
resolve ambiguous uses (chemical versus music industry; power supply;
mathematical/code products). The first token of a document has a stronger
response, and "of" retains part of the preceding cue. Everything else is
zero. Reset history per document. This deliberately omits weak, idiosyncratic
token-specific responses.
"""
import re

READS = ()

# Semantically related words share a response, not individual token-id weights.
GROUPS = (
    (-1.10, 'industry manufacturer manufacturers manufacture supplier suppliers'),
    (-0.90, 'trade commerce brand brands'),
    (-0.75, 'market markets industries manufacturing production'),
    (-0.65, 'industrial products consumer consumers ingredients ingredient'),
    (-0.50, 'business businesses goods commodity commodities ltd farm farming '
            'farmer farmers agriculture agricultural organic environmental '
            'safety safe regulatory counterfeit fake'),
    (-0.38, 'product produced producing producer producers chemical chemicals '
            'plastic waste food foods quality retail'),
    (-0.30, 'company companies demand marketing supplies'),
    (-0.22, 'produce produces'),
    (-0.80, 'supply'),
)
WORDS = {w: value for value, words in GROUPS for w in words.split()}
CHINESE = (
    (-1.70, ('品牌', '名牌', '商标', '商標', '农产品', '農產品')),
    (-1.45, ('生产', '生產', '养殖', '養殖', '贸易', '貿易', '厂家')),
    (-1.10, ('食品', '产业', '產業')),
    (-0.90, ('企业', '企業', '行业', '行業')),
    (-0.80, ('产品', '產品', '市场', '市場', '加工', '消费', '消費')),
    (-0.55, ('商品', '製品', '经营', '經營', '营销', '销售', '銷售', '制造')),
)
MATH = re.compile(r'\b(dot|cross|matrix|tensor|scalar|cartesian|polynomial|'
                  r'multiply|multiplication|factor|factors|integer|prime|'
                  r'sum|permutation|digit|digits)(?:\b|_)|[=;{}]')


def cue(raw):
    w = raw.strip().casefold()
    if w in WORDS:
        value = WORDS[w]
        return value * (0.65 if raw and not raw[0].isspace() else 1.0)
    for value, meanings in CHINESE:
        if any(term in w for term in meanings):
            return value
    if w in set('品产產産製货貨业業商企厂'):
        return -0.60
    if w.startswith(('производ', 'произвед')):
        return -1.40
    if w.startswith(('рын', 'торг', 'продукц')):
        return -0.95
    if w.startswith(('produit', 'produt', 'produkt', 'produ', 'бизнес')):
        return -0.40
    if w.startswith(('manufact', 'indust')):
        return -0.85
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_cue, recent = '', 0.0, ''
        first = True
    else:
        _, previous, previous_cue, recent = carry
        first = False
    raw = prefix.token_strings[-1]
    w = raw.strip().casefold()
    base = cue(raw)
    value = base * (1.9 if first else 1.0)
    if w in {'industry', 'industries'}:
        if previous in {'chemical', 'pharmaceutical', 'food'}:
            value = -1.95
        elif previous in {'music', 'film', 'entertainment'}:
            value = -0.50
    elif w == 'supply' and previous == 'power':
        value = 0.08
    elif w in {'chain', 'chains'} and previous == 'supply':
        value = -1.32
    elif w in {'name', 'names'} and previous in {'brand', 'trade'}:
        value = -1.10
    elif w in {'product', 'products'} and MATH.search(recent):
        value *= 0.12
    elif w == 'of':
        value = 0.40 * previous_cue
    return (doc, w, base, (recent + raw.casefold())[-120:]), float(value)

"""Detect historical/official vocabulary and the partitive phrase 'one of'.

Ranks and military units get positive values, increased near military cues.
History words and selected Asian office, military and territorial spellings
also get positive values. Split English words are joined; state resets at a
new document. Unlisted vocabulary is zero, omitting many weak responses.
"""
import re

READS = ()
HISTORY = {'history': .59, 'historical': .72, 'historically': .53,
           'historic': .33, 'histories': .50, 'historian': .43,
           'histor': .43, 'hist': .20, 'past': .18}
RANKS = {'general', 'major', 'captain', 'lieutenant', 'colonel', 'sergeant',
         'admiral', 'marshal', 'brigadier', 'commander', 'officer', 'sir'}
UNITS = {'army', 'squadron', 'regiment', 'battalion', 'corps', 'cavalry',
         'infantry', 'soldier', 'troop', 'guard', 'headquarters', 'command'}
OFFICES = {'office', 'official', 'deputy', 'governor', 'sheriff', 'ambassador',
           'lord', 'duke', 'baron', 'earl', 'prince', 'count'}
CUES = RANKS | UNITS | {'military', 'police', 'war', 'inspector', 'attorney',
                       'secretary', 'governor', 'director'}
WORDS = set(HISTORY) | RANKS | UNITS | OFFICES
# Related character spellings have coarser calibration than English words.
CJK = {
    **dict.fromkeys({'史', '历史', '歷史', '的历史'}, .82),
    **dict.fromkeys({'官', '司', '佐', '曹', '宰', '관', 'phủ'}, .70),
    **dict.fromkeys({'府', '侍', '丞'}, 1.15),
    **dict.fromkeys({'軍', '守', '郎', '臣', '判', '卫', '衛', '御'}, .45),
    **dict.fromkeys({'军', '將', '隊', '士', '令', '使', '侯'}, .32),
    **dict.fromkeys({'将', '兵', '队'}, .18),
    **dict.fromkeys({'州', '县', '縣', '郡'}, .36),
    **dict.fromkeys({'京', '省', '都', '國', '国', '部', '事', '書', '书'}, .22),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, cues, tail = '', (), ''
    else:
        prev, cues, tail = carry[1:]
    token = prefix.token_strings[-1]
    raw = token.strip().strip('-')
    word = raw.lower()
    match = re.search(r'[A-Za-z]+$', (tail + token)[-40:])
    tail = match.group() if match else ''
    fragment = (token.isalpha() and word not in WORDS
                and tail.lower() in WORDS)
    if fragment:
        raw, word = tail, tail.lower()
    base = word
    if word.endswith('s') and word[:-1] in WORDS:
        base = word[:-1]
    value = HISTORY.get(base, 0.0)
    if base in RANKS:
        value = .55
        if base in {'captain', 'commander', 'officer'}:
            value = .30
        if base in {'general', 'major', 'sir'}:
            value = {'general': .23, 'major': .15, 'sir': .38}[base]
            value += .24 * raw[:1].isupper()
        value += .40 if prev in CUES else .20 if any(cues) else 0.0
    elif base in UNITS:
        value = .60 if base in {'squadron', 'cavalry', 'infantry', 'corps'} else .30
        if base in {'guard', 'command'}:
            value = .08
        value += .40 if prev in CUES else .14 if any(cues) else 0.0
    elif base in OFFICES:
        value = .20
    if word == 'of':
        value = .67 if prev == 'one' else .35 if prev == 'each' else 0.0
        if prev in {'many', 'either', 'two', 'both', 'more', 'any', 'some', 'all'}:
            value = .15
        if prev in {'earl', 'duke', 'prince', 'general', 'governor', 'mayor'}:
            value = .42
    if fragment:
        value *= .75
    value = CJK.get(word, value)
    return (doc, word, (cues + (base in CUES,))[-5:], tail), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:3433 -- a "titles and history" detector.

What it does, in plain terms: this component switches on for words that name military
ranks, units and official offices (General, Lieutenant, Infantry, Sir, governor, and the
classical Chinese office characters 相 丞 宰 令 官 将 司 府 使 副 史 ...), for history
words (history, historical, historian), and for the word "of" right after a quantity
word, as in "One of the ..." or "each of ...". Those are the places where the component's
activation is clearly positive. Everywhere else it predicts 0; the component's real
activation there is a diffuse, small, mostly unexplained background.

Values are the average activations measured on training text: capitalised titles and
"one of" are strongest, lowercase military words weaker.

Limits: this explains only a few percent of the activation variance (about 0.08 on
training text). Most of the variance is a diffuse background that has no simple
word-level description.
"""

READS = ()

# Capitalised titles, as they appear in a name or rank ("General Washington", "Sir John").
TITLES = {
    "General", "Lieutenant", "Colonel", "Marshal", "Captain", "Major", "Sir", "Governor",
    "Commander", "Sergeant", "Infantry", "Cavalry", "Officer", "Deputy", "Commissioner",
}
# Lowercase military and office words.
MILITARY = {
    "general", "generals", "lieutenant", "colonel", "marshal", "commander", "officer",
    "officers", "army", "troops", "soldier", "soldiers", "infantry", "cavalry", "regiment",
    "corps", "artillery", "captain", "militia",
}
OFFICE = {"sir", "governor", "mayor", "deputy", "commissioner", "sheriff", "official", "officials"}
HISTORY = {"history", "historical", "historian", "historians", "historic", "historically"}
# Classical Chinese office and command terms (chancellor, minister, command, official...).
CHINESE_OFFICE = set("相丞宰令官将司府辅使副史帅厅郎")
# Quantity words that precede a partitive "of".
QUANTITY = {
    "one", "each", "many", "two", "three", "several", "any", "both", "most", "some",
    "all", "none", "more", "much", "few", "half", "either", "neither",
}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    s = strings[-1]
    w = _word(s)
    # The previous token counts only if it is in the same document.
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(strings[-2]) if same_doc else ""
