"""A document-opening pulse, especially for headings, imports and sentence starters.

The first token of each packed document receives a text-class-dependent pulse.
Digits and word fragments receive little; explicit headings, source-file imports,
and common sentence openings receive more. Case and token length approximate the
remaining opening words. Chat and tool delimiters have a smaller
position-dependent response; closing a tool is different from closing ordinary
text. Other later tokens stay near zero. Document labels reset the position.
"""

from math import sqrt

READS = ()


def opening(token):
    word = token.strip()
    if token == '<|im_start|>':
        return 1.23
    if word in {'<|im_end|>', '<tool_call>', '<tool_response>',
                '</tool_call>', '</tool_response>', '</think>'}:
        return 1.0
    if word == '<|endoftext|>':
        return 0.61
    if '\ufffd' in token:
        return 0.0
    if token.startswith(' ') and word:
        if word == 'the':
            return 0.38
        if word == 'The':
            return 0.58
        if not any(c.isalnum() for c in word):
            return 0.28
        base = 0.17 if word.istitle() else 0.14
        return base + 0.012 * min(len(word), 8)
    if word == 'Title':
        return 4.10
    if word and set(word) == {'#'}:
        return 4.05 - 0.69 * len(word) if len(word) <= 3 else 0.50
    if word.startswith('#include'):
        return 1.76
    if word.startswith('#'):
        return 1.15
    if word in {'package', 'import'}:
        return 2.53
    if word in {'from', 'def', 'class', 'const', 'export', "'use"}:
        return 1.15
    if word == 'using':
        return 0.66
    if token == '//':
        return 1.49
    if token == '/*':
        return 1.78
    if token.startswith('//'):
        return -0.10
    if word.startswith('/*') or word in {'<?', '"""'}:
        return 1.0
    if word.isdecimal():
        return -0.10
    if not word:
        if token == '\n':
            return 0.49
        return 0.34 if len(token) > 1 else 0.24
    if word == 'The':
        return 1.74
    if word == 'This':
        return 1.64
    if word == 'What':
        return 2.70
    if word == 'How':
        return 1.90
    if word in {'Why', 'Which', 'When', 'Where', 'Who'}:
        return 1.20
    if word in {'I', 'We', 'You', 'It', 'There'}:
        return 1.05
    if word in {'A', 'An', 'In', 'If', 'Is', 'Can', 'Welcome', 'Please', 'Let'}:
        return 1.10
    if word in {'Today', 'Published', 'Question'}:
        return 1.05
    length = min(len(word), 8)
    if not any(c.isalnum() for c in word):
        return 0.38 if length == 1 else 0.29
    if word.isupper():
        return 0.34 if length == 1 else 0.08 + 0.035 * length
    if word[0].isupper():
        return 0.30 + 0.02 * length
    if word.islower():
        return 0.06 + 0.035 * length
    return 0.10 + 0.05 * min(length, 5)


# Later markup responses fade with distance from the document opening.
# Each entry is (long-run level, opening strength, decay power).
MARKUP_DECAY = {
    '<|im_start|>': (-0.14, 0.63, 0.33),
    '<|endoftext|>': (-0.03, 1.05, 0.67),
    '<tool_call>': (-0.08, 0.58, 0.50),
    '<tool_response>': (0.07, 0.67, 0.50),
    '</tool_call>': (-0.11, 1.11, 0.67),
    '</tool_response>': (-0.12, 1.41, 0.67),
    '</think>': (-0.22, 0.69, 0.50),
}


def later(token, previous, position):
    if token == '<|im_end|>':
        if previous == '</tool_call>':
            return 0.14 + 1.37 / sqrt(position + 1)
        if previous == '</tool_response>':
            return 0.18 + 1.39 / (position + 1) ** 0.67
        return -0.18 + 1.09 / sqrt(position + 1)
    if token in MARKUP_DECAY:
        base, strength, power = MARKUP_DECAY[token]
        return base + strength / (position + 1) ** power
    if previous == '<|im_start|>':
        if position == 1:
            return {'user': 0.31, 'assistant': 0.60, 'system': 0.52}.get(
                token, 0.0)
        if token == 'assistant':
            return 0.05
        if token == 'user':
            return -0.02 + 0.32 / (position + 1)
    if token == '#':
        return -0.08 + 0.52 / sqrt(position + 1)
    if token == 'import':
        return 0.11
    return 0.04 if position == 1 else -0.0032


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    value = opening(token) if position == 0 else later(token, previous, position)
    return (document, position, token), float(value)

