at document boundaries; weaker and longer-range responses are not modeled.
"""
READS = ()
COPULAS = {'is': 1.0, 'are': 0.95, 'was': 0.87, 'were': 0.8,
           'be': 0.8, 'been': 0.7, 'being': 0.75, 'am': 0.65,
           "'s": 0.45, '’s': 0.45, "'re": 0.8, '’re': 0.8,
           "'m": 0.65, '’m': 0.65}
