            'he': 1.1, 'she': 1.0, 'they': 1.4, 'you': 0.7, 'we': 0.5,
            'these': 1.4, 'those': 1.2, 'something': 1.0, 'such': 1.0,
            'said': 1.0, 'saying': 1.6, 'wondering': 1.7, 'thinking': 0.8,
            'so': 0.5, 'then': 0.45, 'like': 0.55, 'because': 0.7}


