    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1].strip()
    word, prev = token.lower(), previous.lower()
    be = COPULAS.get(prev, 0.0)
