        elif prev in {'still', 'not', 'always', 'simply', 'also', 'already'}:
            value = -2.9
        elif prev in {'as', 'out', 'or', 'get', 'say', 'says'}:
            value = -2.2
        elif prev in {'maybe', 'perhaps'}:
            value = -1.95
        elif prev in {'if', 'that', 'when', 'since', 'then', 'which'}:
            value = -1.3 if not (prev == 'if' and initial) else -1.02
        elif prev == 'where':
            value = -0.8
    elif be and word in STRENGTH:
        value = -be * STRENGTH[word]
        if initial and prev == 'is' and word in {'it', 'this'}:
            value -= 0.55
    elif token == word:
        if word in {'that', 'it', 'this'}:
            if prev in {'do', 'does', 'did', 'have', 'has', 'had',
                        'get', 'find', 'found', 'call', 'like'}:
                value = -0.5
            elif prev in {'make', 'makes', 'making', 'made'}:
                value = -1.0 if word == 'it' else -0.45
            elif prev in {'not', 'just', "'t", '’t'}:
