    ('make makes made making', 0.90),
    ('add adds added adding', 0.86),
    ('return', 0.95),
    ('returns returned returning', 0.68),
    ('allow allows allowed allowing', 0.68),
    ('generate generates generated generating', 0.73),
    ('produce produces produced producing', 0.46),
    ('arise arises arose arising arisen', 0.63),
    ('assert', 0.82),
    ('asserts asserted asserting', 0.21),
    ('addition additions production', 0.20),
    ('generation generator generators formation', 0.29),
    ('additive additives assertion assertions assertionerror', 0.36),
    ('formed forming', 0.30),
)
