    if name in {'assertequals', 'assertequal', 'asserttrue', 'assertfalse'}:
        return 0.70
    if name in {'addall', 'addobject', 'additem'}:
        return 0.60
    if word in {'the', 'a', 'an'} and prev in MAKE:
        return 0.24 if word == 'the' else 0.17
    if word == 'of' and prev in RESULT_NOUNS:
        return STRENGTH[prev]
