    if word in {'誕', '誕生', '诞生'}:
        return 0.85
    if word.startswith('добав'):
        return 0.60
    if word == '回':
        return 0.53
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token.strip()), float(response(token, previous))

