OR_WORDS = {"or", "/or"}
FOREIGN_CONJUNCTIONS = {
    "und", "и", "et", "ou", "oder", "och", "og", "dan", "và", "или", "și",
    "ve", "nor", "和", "或", "及", "以及", "并", "와",
}
AMPERSANDS = {"&", "&&", "、"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in AND_WORDS:
        value = -3.3
    elif token in OR_WORDS:
        value = -1.5
    elif token in FOREIGN_CONJUNCTIONS:
        value = -0.9
    elif token in AMPERSANDS:
