        if rhyme == 'ong':
            return 1.349 if after <= 1 and before != 2 else 0.593
        if rhyme == 'eng':
            return 1.641 if after == 0 else (0.804 if before <= 1 else 0.176)
        return 1.078 if after == 0 and before <= 2 else 0.538
    if 'инг' in lower:
        return 0.906
    if 'ing' in s:
        if s.startswith(ING_ROOTS):
            return 0.796
        if s in ('during', 'morning'):
            return 0.587
