        before = s.find(cluster)
        if before < 0:
            continue
        at_end = s.endswith(cluster)
        if cluster == 'ank':
            return 1.029 if at_end else 0.652
        if cluster == 'ink':
            return -0.038 if 'think' in s else 0.669
        if cluster == 'unk':
            return 0.098 if 'unknown' in s else 0.509
        if before >= 3:
            return 0.038
        if cluster == 'anc':
            return 1.065 if at_end else 0.399
        return 0.983 if s == 'ant' and text.startswith(' ') else 0.429
    if s in ('nc', 'nk'):
        return 0.689
