    if not (s == 'and' and text.startswith(' ')):
        for cluster in ('and', 'ond', 'ont', 'unt', 'inc', 'unc', 'amp', 'amb'):
            before = s.find(cluster)
            if 0 <= before <= 3:
                if len(s) - before - 3 <= 1:
                    return 0.866 if cluster == 'amb' else 0.292
                break
    return 0.007


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    s = text.strip()
    # Common grammatical/directional Han characters are weak exceptions.
    if s in frozenset('上中向方两兩能更并並让讓'):
        value = -0.043
    elif any(c in HAN_ANG for c in s):
        value = 0.819 if len(s) == 1 else 0.276
    elif any(c in HAN_OTHER_NG for c in s):
        value = 0.417 if len(s) == 1 else 0.149
    elif any(0 <= ord(c) - 0xAC00 < 11172 and
             (ord(c) - 0xAC00) % 28 == 21 for c in s):
        # Hangul final ㅇ; medial ㅏ/ㅑ gets the stronger ANG estimate.
        c = next(c for c in s if 0 <= ord(c) - 0xAC00 < 11172 and
                 (ord(c) - 0xAC00) % 28 == 21)
        vowel = ((ord(c) - 0xAC00) // 28) % 21
        value = 1.080 if vowel in (0, 2) else 0.463
