NONZERO_DIGITS = frozenset('123456789')
NUMBER_DIGITS = {'1': 0.90, '2': 0.57, '3': 0.13}
AFTER_ZERO = {'1': 0.09, '3': -0.23, '4': -0.19, '5': -0.15}
DECIMAL_DIGITS = {'1': 0.40, '2': 0.26}
ARTICLES = {'a': -1.66, 'an': -2.11, 'the': -3.17,
            'A': 0.29, 'An': 0.08, 'The': 0.47}
FUNCTION_WORDS = set('''in on at by to from of for with without as
    i you he she it we they me us him her them my your our his its
    is are was were be has have can will and or but so if when
    while then that which who where how why what this'''.split())
SUFFIXES = set('''ing ed er ers ation ations tion sion able ible
    ity ly ment ness ous ive'''.split())
SOURCE_OPENERS = {'package': 0.61, 'import': 0.03, 'namespace': 0.12}
DECLARATIONS = {'def', 'using', 'public', 'private', 'void', 'require'}


def opening(token):
    if token in ARTICLES:
        return ARTICLES[token]
    if token in SOURCE_OPENERS:
        return SOURCE_OPENERS[token]
    if token == 'Title':
        return 1.48
    if token.isascii() and token.isalpha():
        if token.islower():
            if token in FUNCTION_WORDS:
                return -1.8
            if token in SUFFIXES or token in DECLARATIONS:
                return -0.5
            return -1.35 if len(token) <= 2 else -1.2
        if token.lower() in FUNCTION_WORDS:
            return 0.15
        return -0.15 if len(token) > 1 else 0.05
    if token.startswith('<|'):
        return -0.25
    if token.isalpha():
        return -0.22
    if token == '\n':
        return -0.27
    return 0.08 if token == ' ' else -0.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, before_previous, first_word = 0, '', '', False
    else:
        _, position, previous, before_previous, first_word = carry
    value = 0.0
    if position == 0:
        value = opening(token)
        first_word = token.isascii() and token.isalpha() and token.islower()
    elif first_word:
        first_word = not any(c.isspace() for c in token)
        if first_word and token.strip('_').isalpha():
            value = -0.75 / (1 + 0.4 * (position - 1))

    if token == 'import' and position > 0:
        value = 0.62 if ';' in previous else 0.15
    if token == '\x00':
        value = -0.43
    if len(token) == 1 and token in '0123456789':
        value = 0.0
