            value = NUMBER_DIGITS.get(token, 0.0)
        elif previous == '0':
            value = AFTER_ZERO.get(token, 0.0)
        elif previous == '.' and before_previous in NONZERO_DIGITS:
            value = DECIMAL_DIGITS.get(token, 0.0)
        elif position == 0:
            value = 0.78 if token == '1' else 0.13
    return (doc, position + 1, token, previous, first_word), value

