    elif word in {'верх', 'поверх'} or stem in {'vert', 'verts', 'ceil'}:
        value = -0.24
    elif stem == 'roof':
        value = -0.74 if token.startswith(' ') else -0.45
    elif stem in {'roofs', 'rooftop'}:
        value = -0.36
    elif stem in {'roofing', 'ceiling', 'ceilings', 'tops'}:
        value = -0.58
    elif stem in {'topping', 'underside'}:
        value = -0.43
    elif stem in {'dome', 'domes', 'zenith'}:
        value = -0.91 if stem == 'zenith' else -0.81
    elif stem in HIGH_POINTS:
        value = -0.35
    elif stem in UPPER_PARTS:
        value = -0.15
    elif stem in HEAD_AND_SUPPORT or stem in EXTREMES:
        value = -0.29
    elif word in {'头', '頭', '额', '額', '項', '領'}:
