    (-0.34, 'authority discretion oversight autonomy accountable '
            'accountability veto власти власть'),
    (-0.32, 'democracy democr democratic deliber'),
    (-0.28, 'elections elected shareholders stakeholders representatives councils'),
    (-0.19, 'approval approvals approve powers legislature committees '
            'permissions delegates'),
    (-0.13, 'decision decisions council committee governing govern authorities'),
    (-0.12, 'leadership leader leaders executives'),
    (-0.09, 'board boards executive election electoral vote voting civic'),
    (-0.21, 'officials bureaucracy'),
    (-0.26, 'governance supervision oversee oversees overseeing empowered'),
    (-0.20, 'delegation sovereignty legitimacy governors trustees treasurer'),
    # General institutional descriptors have the opposite, weaker sign.
    (0.06, 'public civil official party national district municipality'),
    (0.10, 'parties occupation'),
    (0.20, 'territorial'),
)
