    (-0.85, '监督 职权 职能'),
    (-0.47, '决策 民主 权力 自治 审议 选举 表决 开会 行使 上级'),
    (-0.35, '人大 代表大会 人大代表 委员会 常务 常委会 享有'),
    (-0.29, '监管 权限 权利 协商 审批 分红 集体经济 问责'),
    (-0.18, '领导 代表 参与 会议 成员 权 主任 职责 选拔'),
