    if token == '权' and tail.endswith(('决策', '投票')):
        value = -1.05
    if token in ('成员', '代表') and re.search(
            r'(领导班子|委员会|代表大会)$', tail):
        value = -0.90
    if token in ('论', '論') and re.search(r'(政|政治理)$', tail):
        value = 0.55
    # Isolated governance words at a document boundary have no other context.
    if not tail and word in ('decision', 'decisions', 'approval', 'officials', 'elected',
                              'members', 'directors', 'trustee'):
        value = -0.75
    if not tail and word in ('board', 'committee', 'council'):
        value = -0.52
    if not tail and word in ('power', 'member', 'meeting'):
        value = -0.33
    if not tail and token.strip() in CHINESE:
        value *= 2.0
    if not tail and token.strip() in ('"""', '/**'):
        value = 0.30
    # Weak continuation of an authority phrase through relational prepositions.
    if previous < -0.10 and word in ('of', 'to', 'in', 'for', 'from', 'the'):
        value += 0.30 * previous
    if previous < -0.10 and word in ('by', 'over'):
        value += 0.75 * previous
    return (doc, (tail + token)[-90:], value), float(value)

"""Approximate the response to the next token after a source/origin cue.

'From' is the main cue, in prose and in identifiers.  Relative locations,
times, state changes, conversion types and quoted import paths respond most;
articles and possessives respond little.  A weaker cue persists through 'the'.
Related source/self compounds and code string openings are secondary patterns.
The rounded values summarize training observations; away from these cues the
prediction is zero. State resets at each document boundary.
"""
READS = ()

POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
LOCATIONS = {'left', 'right', 'there', 'above', 'below', 'inside', 'outside',
             'under', 'around', 'behind', 'within', 'over', 'across', 'out',
             'afar', 'beyond', 'underneath', 'home', 'where', 'heaven'}
REFERENCES = {'rest', 'beginning', 'first', 'point', 'place', 'day', 'age'}
QUANTIFIERS = {'one', 'all', 'every', 'what', 'about', 'least'}
CONVERSION_TYPES = {'dict', 'tuples', 'records', 'entries', 'keys', 'string',
                    'html', 'xml', 'list', 'array', 'slice', 'file', 'object',
                    'context', 'utf', 'bytes', 'bits', 'url', 'timestamp',
                    'iso', 'integer', 'index'}
PYTHON_MODULES = {'datetime', 'collections', 'urllib', 'django', 'sklearn',
                  'nltk', 'tkinter', 'flask', 'keras', 'numpy', 'pandas',
                  'threading', 'tqdm', 'pymongo', 'tensorflow', 'sqlalchemy'}


def after_origin(token):
    word = token.strip().lower()
    if word.startswith(('"', "'")):
        path = word[1:]
        if path == '@':
            return 5.3
        if path.startswith(('./', '../', '@')):
            return 2.8
        return 1.45
    if word == 'the' or word in POSSESSIVES:
        return 0.08
    if word in {'a', 'an', 'this', 'these', 'those', 'it', 'them', 'you'}:
        return 0.3
    if word in {'now', '现在', '現在'}:
        return 4.4
    if word in {'time', 'here', 'being'}:
        return 3.0
    if word in LOCATIONS or word in REFERENCES or word in QUANTIFIERS:
        return 1.8
    if word in {'each', 'another', 'that', 'which', 'both', 'any'}:
        return 0.85
    if word == 'typing':
        return 3.3
    if word in PYTHON_MODULES:
        return 1.8
    if token.isascii() and not token[:1].isspace():
        name = word.lstrip('_-')
        if name in {'json', 'iter', 'str'}:
            return 4.0
        if name in CONVERSION_TYPES:
            return 2.6
        if token.isidentifier() or token.startswith(('_', '-')):
            return 1.25
    return 0.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, delayed = '', False
    else:
        previous, delayed = carry[1:]
    token = prefix.token_strings[-1]
    old = previous.strip().lower().lstrip('._-(/')
    word = token.strip()
    value = 0.0
    if old == 'from':
        value = after_origin(token)
    elif delayed and old == 'the':
        value = 0.38 * after_origin(token)
    elif old == 'source' and word.lower() == 'code':
        value = 1.0 if token.startswith(' ') else 1.9
    elif old == 'source' and word.lower().lstrip('-_') in {'map', 'maps'}:
        value = 1.4
    elif old == 'self' and word.startswith('-'):
        value = 0.7
    elif old == '#include' and word.startswith(('<', '"')):
        value = 0.95
    elif previous.strip() in {'从', '從', '来自', '來自', '由'}:
        value = max(0.65, after_origin(token))
    elif previous.strip() == '自':
        value = 1.5
        if word in {'然', '己'}:  # natural / oneself
            value = 0.15
        elif word == '慰':  # self-comfort
            value = 2.6
        elif word == '拍':  # self-photography
            value = 0.75
    elif old in {'=', '==', '==='} and token.startswith((' "', " '")):
        value = 0.4
    elif token in {'("', "('", '{"', " '"}:
        value = 0.18
    return (doc, token, old == 'from'), float(value)

programs.haiku:
"""Draft 4: fires on the word right after 'from' (and the Chinese/Korean words for 'from').

The word after 'from' is strongest when it is a quantifier or adverb (`from all`,
`from one`, `from time`, `from here`) or a code module path (`from './x'`, `from '@x'`),
moderate after other words, and nearly silent after determiners (`from the`, `from their`).
A few other spots that follow a from-like or code operator also fire mildly."""

READS = ()

FROM_WORDS = {"自", "从", "由", "자"}  # Chinese and Korean words for "from"
DETERMINERS = {"the", "their", "your", "our", "his", "her", "its", "my", "these", "them"}
QUANTIFIERS = {"all", "one", "each", "another", "both", "rest", "beginning", "above",
               "there", "here", "home", "time", "being", "which", "that"}


def opens_line(prefix):
    """True if the token before the current one is the first thing on its line."""
    i = len(prefix.token_strings) - 3
    while i >= 0 and prefix.token_strings[i].strip() == "":
        if "\n" in prefix.token_strings[i]:
            return True
        i -= 1
    return i < 0 or "\n" in prefix.token_strings[i]


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    before = prefix.token_strings[-2].strip()
    word = prefix.token_strings[-1].strip()
    if before.lower().endswith("from") or before in FROM_WORDS:
        if word.lower() in DETERMINERS:
            return None, 0.05
        if before == "from" and opens_line(prefix):
            return None, 0.9  # import statement: `from typing import ...`
        if word.lower() in QUANTIFIERS or (word and word[0] in "'\"@.") or "_" in word:
            return None, 1.4
        if before != "from":
            return None, 1.2  # From, FROM, _from, .from, 自, 从 ...
        return None, 0.4
    if before == "#include" and word[:1] in ("<", '"'):
        return None, 0.9
    if before in ("===", "==", "!==", "=") and word[:1] in ("'", '"'):
        return None, 0.6
    return None, 0.0

programs.sol:
"""Token-level cues for change, becoming, variation, or staying unchanged.

Change/become words give negative responses. Single Chinese/Japanese change
characters respond most strongly; compounds respond less. The signal can also
continue into the next grammatical linker or a split word ending. This is a
lexical approximation, not a sentence-level semantic classifier. There are
secondary responses to the characters 便/改 and to byte-split long-s (ſ).
"""
READS = ()
CHANGE_VERBS = frozenset('change changes changed changing'.split())
BECOME_VERBS = frozenset('become becomes became becoming'.split())
VARIATION_WORDS = frozenset('variant variants variation variations variable '
                           'variables transform transformation'.split())

# Related word forms share a response rather than having token-id entries.
WORD_CLASSES = (
    (-2.25, 'change changes changed changing'),
    (-1.7, 'become becomes'),
    (-1.42, 'became becoming'),
    (-1.5, 'unchanged'),
    (-1.3, 'variant variants invariant'),
    (-0.93, 'variation variations'),
    (-0.83, 'variable'),
    (-0.41, 'variables'),
    (-0.56, 'variability vary varies varying varied'),
    (-0.78, 'vari'),
    (-0.25, 'var'),
    (-0.2, 'variance'),
    (-0.86, 'transform transforms transformed transforming transformation '
             'transformations transformer'),
    (-0.7, 'alter alters altered altering alteration alterations'),
    (-0.76, 'remain remains remained'),
    (-0.36, 'remaining stay stays stayed staying'),
    (-0.55, 'fixed disappear obsolete'),
    (-0.46, 'mutate mutation mutations evolve evolves'),
    (-0.3, 'modification modifications evolving disappears disappeared'),
    (-0.15, 'modify modifies modified modifying evolved evolution'),
    (-0.27, 'exchange exchanges exchanged exchanging'),
)
WORD_RESPONSE = {word: value for value, words in WORD_CLASSES
                 for word in words.split()}
CHANGE_LINKERS = {'of': -1.1, 'in': -0.75, 'the': -0.3,
                  'to': -0.3, 'it': -0.3, 'this': -0.3}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    bare = token.strip().lstrip('._-/')
    word = bare.lower()
    value = WORD_RESPONSE.get(word, 0.0)
    if word in CHANGE_VERBS:
        if token.isupper() or (token == bare and bare.islower()):
            value = -1.6
    elif word == 'chang':
        value = -1.1 if bare.islower() else -0.6
    elif 'Change' in bare or 'Changed' in bare:
        value = -1.15  # Change-event identifiers in code.
    elif word == 'fixed' and bare.isupper():
        value = -1.2

    # Change/become stems in Spanish, Vietnamese, Turkish, Indonesian, Russian.
    if word in {'cambios', 'cambiar', 'cambi', 'camb', 'đổi', 'menjadi'}:
        value = -1.1
    elif word in {'cambio', 'değiş'}:
        value = -1.6
    elif word == 'biến':
        value = -1.9
    elif word == 'измен':
        value = -1.65
    elif word.startswith('изменени'):
        value = -0.95
    elif word.startswith('перемен'):
        value = -1.1
    elif word in {'стал', 'стала', 'стало', 'стали'}:
        value = -0.45
    elif word in {'станет', 'становится'}:
        value = -0.75

    chinese = bare.replace('變', '变')
    if chinese == '变':
        value = -9.1 if bare == '变' else -7.5
    elif chinese == '不变':
        value = -6.0
    elif chinese == '变了':
        value = -4.8
    elif '变得' in chinese or '变为' in chinese:
        value = -3.5
    elif any(w in chinese for w in ('变化', '变成', '变更')):
        value = -2.85
    elif '改变' in chinese:
        value = -2.2
    elif '变量' in chinese:
        value = -1.0
    elif '变' in chinese:
        value = -1.8
    elif bare == '変':
        value = -5.0
    elif '変' in bare:
        value = -1.4
    elif bare in {'便', '改'}:
        value = -0.75
    elif bare == '成为':
        value = -0.55
    elif bare == '更改':
        value = -0.96
    elif bare == '변':
        value = -3.9 if token.startswith(' ') else -2.65
    elif bare in {'변경', '변화'}:
        value = -2.0 if bare == '변경' else -1.5

    # One-token continuation: grammatical linkers and split word endings.
    if value == 0.0:
        if previous in CHANGE_VERBS:
            value = CHANGE_LINKERS.get(word, 0.0)
            if word == 'of' and previous != 'change':
                value = -0.7
            elif word == 'in' and previous in {'changed', 'changing'}:
                value = -0.3
        elif previous in BECOME_VERBS:
            if word in {'a', 'an', 'the', 'more'}:
                value = -0.1 if word == 'more' else -0.16
        elif previous in VARIATION_WORDS:
            value = {'of': -0.27, 'in': -0.2, 'ations': -0.5,
                     'ation': -0.5, 'ed': -0.5, 'ing': -0.5}.get(word, 0.0)
        elif previous == 'измен':
            if word == 'ений':
                value = -1.27
            elif word.startswith('ени'):
                value = -0.57
            elif word in {'ить', 'я', 'ять'}:
                value = -0.4
        elif previous in {'变', '變', '変'}:
            value = {'化': -1.3, '更': -0.46, '動': -0.46,
                     '成了': -1.0}.get(bare, 0.0)

    # A byte fragment may complete a character invisible when decoded alone.
    if '\ufffd' in token:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in {'变', '變', '変'}:
            value = {'变': -10.45, '變': -5.1, '変': -4.1}[completed]
            word = completed
        elif completed == 'ſ':
            value = 1.26
    return (document, word), float(value)

programs.luna:
"""Recognize change and becoming words across several scripts and languages."""

READS = ()

DIRECT = (
    "change", "chang", "变", "改", "變", "перемен", "измен",
)
BECOMING = ("become", "becam", "стал", "变得")
SPANISH_CHANGE = ("cambi",)
RELATED = (
    "vari", "mutat", "alter", "transform", "transit", "remain",
    "unchang", "fixed", "fix", "disappear", "obsolete", "stay",
    "변하", "바뀌",
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = "" if carry is None or carry[0] != doc else carry[1]
    for char in prefix.token_strings[-1]:
        if char.isalpha():
            word += char.lower()
        else:
            word = ""

    if any(word.startswith(stem) for stem in DIRECT):
        value = -2.2
    elif any(word.startswith(stem) for stem in BECOMING):
        value = -1.7
    elif any(word.startswith(stem) for stem in SPANISH_CHANGE):
        value = -1.2
    elif any(word.startswith(stem) for stem in RELATED):
        value = -0.75
    else:
        value = 0.0
    return (doc, word), value

programs.sol:
"""Approximate a lexical 'world' feature and its weaker semantic neighbours.

The largest responses are to world/World, Chinese 世界 and 世, and translations
of 'world'. Lower responses cover Earth, global scope, society, life, the future,
and surrounding space/environment. Capitalization and compound forms matter.

Only the current token and previous token are used. Natural/real/ordinal world
phrases are attenuated, determiners slightly strengthen world, and 'world of'
and 'world's' retain a smaller response. State resets at document boundaries.
Other tokens receive zero. Small residual activations, rarer vocabulary and
context beyond one token are deliberately not modelled.
"""
READS = ()

# Translations and inflections of 'world', grouped by response strength.
WORLD_WORDS = (
    (4.7, {'monde', 'mundo', 'Welt', 'wereld', 'świat', 'świecie', 'świata'}),
    (3.5, {'mondo', 'düny', 'โลก'}),
    (2.5, {'dünya', 'Dünya'}),
    (2.9, {'мира', 'мире', 'миров', 'mundial'}),
    (2.3, {'мир', 'welt', 'العالم', 'عالم', 'thế'}),
    (6.0, {'세계', '세상'}),
)

# Weaker semantic neighbours: physical world, society, life, surroundings.
NEIGHBOURS = (
    (2.3, {'earth', 'globe', 'universe', 'worldwide'}),
    (1.6, {'global', 'globally'}),
    (1.3, {'life', 'future', 'society', 'planet', 'humanity', 'mankind'}),
    (1.0, {'reality', 'international', 'internationally', 'nature',
           'century', 'centuries', 'street', 'streets', 'heaven', 'hell'}),
    (0.8, {'system', 'systems', 'social', 'environment', 'environments',
           'market', 'marketplace', 'american', 'america', 'europe', 'european',
           'internet', 'ground', 'around', 'sphere', 'existence', 'ocean'}),
    (0.6, {'space', 'spaces', 'today', 'modern', 'history', 'living', 'lives',
           'sea', 'sky', 'beyond', 'external', 'surrounding', 'environmental',
           'atmosphere', 'generations', 'generation', 'landscape', 'landscapes'}),
    (0.4, {'outside', 'outer', 'foreign', 'population', 'body', 'mind',
           'soul', 'things', 'city', 'cities'}),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lower()
    if word == 'world':
        if raw.startswith(' '):
            value = 9.4 if text == 'World' else 8.5
        else:
            value = 8.4 if text == 'World' else 7.8
    elif word in {'-world', '(world'}:
        value = 6.5
    elif word == '.world':
        value = 8.0
    elif word == '/world':
        value = 7.2
    elif word == 'orld':  # Fragment of WORLD/world.
        value = 8.6 if text.isupper() else 6.7
    elif word.endswith('world') and word != 'underworld':
        value = 3.0 if 'ello' in word else 5.5
    elif word == 'worlds':
        value = 6.1
    elif word == 'worldly':
        value = 4.5
    elif word == 'worldview':
        value = 2.3
    elif text == '世':
        value = 7.9
    elif text in {'世界', '世界的'}:
        value = 8.5
    elif text == '的世界':
        value = 7.9
    elif text in {'世界上', '世上'}:
        value = 6.1
    elif text == '全世界':  # The whole world.
        value = 4.7
    elif text in {'这个世界', '世间', '世間'}:
        value = 5.7
    elif text.startswith('世界'):
        value = 1.8 if text == '世界杯' else 3.2
    # Chinese neighbours: Earth/global scope; society; life/reality/time;
    # environment, continents and physical surroundings.
    elif text in {'全球', '地球', '天地', '天下'}:
        value = 2.6
    elif text in {'社会', '社會', '宇宙'}:
        value = 2.0
    elif text in {'未来', '现实', '現實', '国际', '國際', '时代', '時代'}:
        value = 1.3
    elif text in {'环境', '環境', '亚洲', '欧洲', '市场', '天', '海', '外'}:
        value = 0.95
    elif text in {'系统', '生活', '空间', '地'}:
        value = 0.6
    elif text == 'мир' and not raw.startswith(' '):
        value = 0.7
    else:
        value = 0.0
        bare = word.lstrip('-_./')
        for strength, words in WORLD_WORDS:
            if text in words:
                value = strength
                break
        else:
            for strength, words in NEIGHBOURS:
                if word in words or bare in words:
                    value = strength if word == bare else 0.8 * strength
                    break
    if word in {'world', '-world'}:
        if previous == 'natural':
            value = 5.0
        elif previous == 'real':
            if word == '-world':
                value -= 0.6
            else:
                value -= 1.1 if text == 'World' else 1.8
        elif previous in {'first', 'second', 'third', 'new'}:
            value -= 0.9
        elif previous in {'the', 'this', 'our', 'his', 'her'}:
            value += 0.3 if text == 'world' else 0.7
    elif previous == 'world':
        if word == 'of':
            value = 2.2
        elif text in {"'s", '’s'}:
            value = 1.5
    return (doc, word), value

programs.haiku:
"""The world-concept detector of layers.0.mlp.down_proj:3451.

This component writes a strong "the world" signal into the residual stream. It fires on
the word *world* itself, whatever its case or spacing ("world", " World", ".world", "ORLD"),
on the Chinese word 世界 (world) and the 世 that begins it, and more weakly on other
languages' words for world (monde, Welt, mundo, мир). Weaker still it fires on words for
the wide, collective scale of things: earth, global, international, Europe, society,
life, future, nature. Everything else is near zero.

The program is stateless: each position is judged from the token just read.
"""

READS = ()

WORLD = 8.0          # "world" and 世界: the component's strongest response
TRANSLATION = 4.5    # other languages' "world": monde, Welt, mundo, mondo, 세계
GLOBAL = 2.0         # earth, global, international, worldwide, planet, universe, 全球, 国际
BROAD = 1.0          # society, life, future, nature, Europe, America, market, ...

TRANSLATIONS = {"monde", "welt", "mundo", "mondo", "세계", "全世界", "мир", "мире"}
GLOBAL_WORDS = {"earth", "global", "globally", "globe", "planet", "universe",
                "international", "全球", "国际", "國際"}
BROAD_WORDS = {"society", "life", "future", "nature", "century", "humanity", "mankind",
               "environment", "system", "systems", "social", "reality", "generations",
               "europe", "european", "america", "american", "market", "internet",
               "around", "modern", "history", "today", "space", "社会", "天下"}


def level(word):
    """How strongly a token (lowercased, spacing removed) evokes the world."""
    if word == "worldview":
        return 0.0
    if "worldwide" in word:
        return GLOBAL
    if "world" in word or "世界" in word or word in ("世", "orld"):
        return WORLD
    if word in TRANSLATIONS:
        return TRANSLATION
    if word in GLOBAL_WORDS:
        return GLOBAL
    if word in BROAD_WORDS:
        return BROAD
    return 0.0


def step(carry, prefix, upstream):
    return carry, level(prefix.token_strings[-1].strip().lower())

