    ('some something someone somebody somewhere', 0.045),
    ('other another others otherwise else', -0.041),
    ('all every everything everyone everybody everywhere both each', 0.016),
    ('only just merely solely', 0.019),
    ('either whether', 0.034),
    ('no not never nothing nobody none nowhere neither nor', 0.012),
    ('very really quite rather extremely absolutely', -0.040),
    ('few little less least', 0.028),
    ('if unless', -0.012),
    ('down below under lower downward downwards', -0.017),
    ('between among across through beyond within', -0.020),
    ('first second third fourth fifth sixth seventh eighth ninth tenth', -0.017),
    ('second minute hour day week month year decade century', -0.015),
)
WORD_CLASSES = tuple((frozenset(words.split()), value)
                     for words, value in WORD_CLASSES)
