    if word == '<|im_start|>':
        value = -0.061 if age == 0 else 0.016
    elif word == '<|im_end|>':
        value = 0.080 - 0.038 / (1 + age / 24)
    elif word == '</think>':
        value = -0.103 + 0.060 / (1 + age / 32)
