        value = -0.19 - 0.55 * decay
    elif word in {'新', '新的', '新しい'}:
        value = -0.09 - 0.26 * decay
    elif word in NEWNESS:
        value = -0.011 - 0.14 * decay
    elif not word:
        if '\n' in raw:
            value = 0.001 + 0.064 / (1 + age / 7)
            value -= 0.013 if raw.count('\n') > 1 else 0.0
            if age == 0:
                value = 0.018
        elif raw == ' ':
            value = -0.082 if age == 0 else -0.001 - 0.022 / (1 + age / 24)
        else:
            value = -0.006 + 0.001 * min(len(raw), 20)
            value -= 0.004 if '\t' in raw else 0.0
    elif any('\u0600' <= c <= '\u06ff' for c in word):
        value = 0.015  # Arabic-script text
    elif any('\u4e00' <= c <= '\u9fff' for c in word):
        value = -0.005  # Han characters
    elif any('\u3040' <= c <= '\u30ff' for c in word):
        value = 0.008  # Japanese kana
    elif any('\uac00' <= c <= '\ud7af' for c in word):
        value = -0.005  # Korean Hangul
    elif '\ufffd' in word:
        value = 0.007  # A byte fragment of a Unicode character
    else:
        text = raw.strip()
        if text.isupper():
            value += 0.005
        elif text.istitle():
            value -= 0.002
        value += 0.012 if '\\' in text else 0.0
        value += 0.010 if "'" in text else 0.0
        for words, bias in WORD_CLASSES:
            if word in words:
                value += bias
    return (doc, age), float(value)

"""Negative boundary pulses, strongest at document onset.

End-of-text and tool-call markers have negative activations. Early line
breaks also do, especially a bare newline; punctuation and blank-line
bundles change their strength. The line-break pulse fades exponentially
with tokens read and is suppressed after explicit chat/formatting openings.
Small onset corrections cover digits, indentation, and formatting symbols.
Ordinary text is approximated by zero, not a vocabulary lookup.
"""
import math

READS = ()
CODE_OPENERS = {'import', 'from', 'package'}
SENTENCE_ENDINGS = set('.!?。！？')


def line_break(token, position):
    """Initial strength and fading strength for familiar line-ending forms."""
    punctuation = token.strip()
    breaks = token.count('\n')
    if not punctuation and not token.strip('\r\n'):
        initial = 5.54 if token == '\n' else 4.73 if breaks == 1 else 3.4
        scale, decay = (3.0, 0.34) if breaks == 1 else (2.6, 0.45)
    elif not punctuation:
        initial = 3.6 if len(token) <= 3 else 2.6
        scale, decay = 1.2, 0.5
    elif all(c in SENTENCE_ENDINGS for c in punctuation):
        initial, scale, decay = 2.7, 2.2, 0.27
    elif punctuation in (';', ',', ')', '()'):
        initial, scale, decay = 3.9, 2.4, 0.4
    elif punctuation in ('{', '}'):
        initial = 3.5 if token[0].isspace() else 1.8
        scale, decay = 1.7, 0.43
    elif any(c in punctuation for c in '/\'"'):
        initial, scale, decay = 2.2, 1.5, 0.4
    else:
        initial, scale, decay = 2.9, 1.9, 0.35
    if breaks > 1 and punctuation:
        initial *= 0.55
        scale *= 0.6
    elif breaks > 1 and token.strip('\r\n'):
        initial *= 0.55
    return -initial if position == 0 else -scale * math.exp(-decay * position)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    text = token.strip()
    if carry is None or carry[0] != doc:
        position, previous_breaks = 0, 0
        if token == '<|im_start|>':
            line_factor = 0.0
        elif text and (set(text) == {'#'} or text.startswith(('```', '#!'))):
            line_factor = 0.05
        elif text in CODE_OPENERS or text.startswith(('<?', '//')):
            line_factor = 0.2
        else:
            line_factor = 1.0
    else:
        _, position, line_factor, previous_breaks = carry
    state = (doc, position + 1, line_factor, token.count('\n'))

    if token == '<|endoftext|>':
        return state, -3.25
    if token == '<tool_call>':
        if previous_breaks == 1:
            value = -0.26
        elif previous_breaks >= 3:
            value = -0.6
        else:
            value = -0.5
        return state, value
    if token == '<|im_start|>':
        return state, -0.246 if position == 0 else 0.04
    if token == '<|im_end|>':
        return state, -0.36 if position == 0 else 0.05
    if '\n' in token:
        value = line_break(token, position)
        return state, value if position == 0 else value * line_factor
    if position == 0:
        if text.isdecimal():
            return state, -0.44 if text == '0' else -0.13
        if token.isspace():
            return state, -0.16 if token == ' ' else -0.47
        if text in CODE_OPENERS or text.startswith(('<?', '#!', '/*')):
            return state, -0.5
        if text and set(text) == {'#'}:
            return state, -0.35 if len(text) == 1 else -0.5
        if token in (',', '.'):
            return state, 0.2
        if text and all(not c.isalnum() for c in text):
            return state, -0.25
    return state, 0.0

